// IT Essentials – Deel II: Hardwarecomponenten – 8: Randapparatuur
// v = vraag, a = antwoord, o = onderwerp (bovenaan de kaart), uitleg = extra uitleg onder het antwoord
// img = afbeelding op de voorkant (map afbeeldingen/ITdeel2les8_randapparatuur/), imgAntwoord = afbeelding op de achterkant (optioneel)
// wit: true = witte kaart die de cursus voorstelt · extra: true = extra info, niet uit de cursus (turquoise rand)
// tabel = kleine overzichtstabel (eerste rij = kolomkoppen)
// De structuur onderaan bepaalt het overzicht rechts (volgorde van de slides).

const kaarten_IT_deel2_les8 = [
  // ===== Basisbegrippen (extra, uit de uitgebreide uitleg van Anicée) =====
  { v: "Wat is een invoerapparaat? Geef voorbeelden.", a: "Een toestel dat informatie naar de computer brengt: toetsenbord, muis, scanner, microfoon.", o: "Basisbegrippen", extra: true,
    uitleg: "Invoer en uitvoer: Invoerapparaten (input) brengen informatie naar de computer: toetsenbord, muis, scanner, microfoon. Uitvoerapparaten (output) brengen informatie van de computer naar jou: scherm, projector, printer, luidsprekers. Sommige doen beide, zoals een netwerkkaart of een headset.\n\nRandapparatuur: Alle toestellen die rond de eigenlijke computer (de kast met processor, geheugen en moederbord) hangen en ermee verbonden zijn: toetsenbord, muis, scherm, printer, scanner, luidsprekers… In het Engels: peripherals. Ze worden aangesloten via de poorten uit hoofdstuk 7." },
  { v: "Wat is een uitvoerapparaat? Geef voorbeelden.", a: "Een toestel dat informatie van de computer naar jou brengt: scherm, projector, printer, luidsprekers.", o: "Basisbegrippen", extra: true,
    uitleg: "Invoer en uitvoer: Invoerapparaten (input) brengen informatie naar de computer: toetsenbord, muis, scanner, microfoon. Uitvoerapparaten (output) brengen informatie van de computer naar jou: scherm, projector, printer, luidsprekers. Sommige doen beide, zoals een netwerkkaart of een headset." },
  { v: "Noem een toestel dat zowel invoer als uitvoer doet.", a: "Een netwerkkaart of een headset.", o: "Basisbegrippen", extra: true,
    uitleg: "Invoer en uitvoer: Invoerapparaten (input) brengen informatie naar de computer: toetsenbord, muis, scanner, microfoon. Uitvoerapparaten (output) brengen informatie van de computer naar jou: scherm, projector, printer, luidsprekers. Sommige doen beide, zoals een netwerkkaart of een headset." },
  { v: "Wat is een pixel?", a: "Eén beeldpunt: een klein stipje op het scherm dat één kleur toont.", o: "Basisbegrippen", extra: true,
    uitleg: "Pixel: Een pixel (picture element) is één beeldpunt: een heel klein stipje op het scherm dat één kleur kan tonen. Een scherm bestaat uit miljoenen pixels in rijen en kolommen." },
  { v: "Wat is resolutie?", a: "Het aantal pixels, geschreven als breedte × hoogte.", o: "Basisbegrippen", extra: true,
    uitleg: "Resolutie: Het aantal pixels van een scherm, geschreven als breedte × hoogte. 1920×1080 betekent 1920 pixels naast elkaar en 1080 rijen onder elkaar. Vermenigvuldig je die, dan krijg je het totale aantal pixels: 1920 × 1080 = 2 073 600 pixels (ongeveer 2,07 miljoen)." },
  { v: "Hoe bereken je het totaal aantal pixels?", a: "Breedte × hoogte, bv. 1920 × 1080 = 2 073 600.", o: "Basisbegrippen", extra: true,
    uitleg: "Resolutie: Het aantal pixels van een scherm, geschreven als breedte × hoogte. 1920×1080 betekent 1920 pixels naast elkaar en 1080 rijen onder elkaar. Vermenigvuldig je die, dan krijg je het totale aantal pixels: 1920 × 1080 = 2 073 600 pixels (ongeveer 2,07 miljoen)." },
  { v: "Wat is een megapixel?", a: "1 miljoen pixels.", o: "Basisbegrippen", extra: true,
    uitleg: "Megapixel (MP): Mega = miljoen. 1 megapixel = 1 miljoen pixels. Een scherm met 2 073 600 pixels heeft dus ongeveer 2,07 MP." },
  { v: "Wat is het verschil tussen analoog en digitaal?", a: "Digitaal = enen en nullen. Analoog = een vloeiend veranderend signaal (zoals een geluidsgolf).", o: "Basisbegrippen", extra: true,
    uitleg: "Analoog en digitaal: Digitaal: informatie in enen en nullen, zoals een computer werkt. Analoog: een signaal dat vloeiend verandert, zoals geluidsgolven in de lucht of de spanning die een luidspreker doet trillen. Veel randapparaten moeten tussen die twee omzetten." },
  { v: "Wat doet een DAC?", a: "Digitaal omzetten naar analoog (Digital-to-Analog Converter).", o: "Basisbegrippen", extra: true,
    uitleg: "DAC en ADC: Een DAC (Digital-to-Analog Converter) zet digitaal om naar analoog, bv. digitale muziek naar een signaal voor je hoofdtelefoon. Een ADC (Analog-to-Digital Converter) doet het omgekeerde: analoog naar digitaal, bv. je stem in een microfoon naar enen en nullen." },
  { v: "Wat doet een ADC?", a: "Analoog omzetten naar digitaal (Analog-to-Digital Converter).", o: "Basisbegrippen", extra: true,
    uitleg: "DAC en ADC: Een DAC (Digital-to-Analog Converter) zet digitaal om naar analoog, bv. digitale muziek naar een signaal voor je hoofdtelefoon. Een ADC (Analog-to-Digital Converter) doet het omgekeerde: analoog naar digitaal, bv. je stem in een microfoon naar enen en nullen." },
  { v: "Wat is een sensor?", a: "Een onderdeel dat iets uit de echte wereld meet (licht, beweging) en omzet in een elektrisch signaal.", o: "Basisbegrippen", extra: true,
    uitleg: "Sensor: Een onderdeel dat iets uit de echte wereld meet (licht, beweging, warmte) en omzet in een elektrisch signaal. In een muis en een scanner zit een lichtsensor." },
  { v: "Wat zijn CMOS en CCD?", a: "Twee soorten lichtsensoren die licht omzetten in een elektrisch signaal.", o: "Basisbegrippen", extra: true,
    uitleg: "CMOS en CCD: Twee soorten lichtsensoren (beeldsensoren) die licht omzetten in een elektrisch signaal, zoals in een fotocamera. CMOS zit bv. in een optische muis en in gsm-camera's, CCD in veel scanners." },
  { v: "Waar staat LED voor?", a: "Light-Emitting Diode: licht-uitstralende diode.", o: "Basisbegrippen", extra: true,
    uitleg: "LED: Light-Emitting Diode: een licht-uitstralende diode, een klein, zuinig lampje dat heel lang meegaat." },
  { v: "Wat is RAM en wat gebeurt er bij stroomuitval?", a: "Het werkgeheugen; het is vluchtig, dus de inhoud is weg als de stroom wegvalt.", o: "Basisbegrippen", extra: true,
    uitleg: "RAM: Het werkgeheugen van de computer. Hierin staan de programma's en bestanden waaraan je nu werkt. RAM is vluchtig: als de stroom wegvalt, is alles wat erin staat weg (zie het hoofdstuk over geheugen)." },
  { v: "Wat is een server?", a: "Een computer die diensten levert aan andere computers (website, e-mail, opslag).", o: "Basisbegrippen", extra: true,
    uitleg: "Server: Een computer die diensten levert aan andere computers, bv. een website, e-mail of opslag. Servers staan vaak samen in een serverpark (datacenter) en moeten dag en nacht werken." },
  { v: "Wat is een serverpark?", a: "Een plaats (datacenter) waar veel servers samen staan.", o: "Basisbegrippen", extra: true,
    uitleg: "Server: Een computer die diensten levert aan andere computers, bv. een website, e-mail of opslag. Servers staan vaak samen in een serverpark (datacenter) en moeten dag en nacht werken." },


  // ===== Inhoud (slide 2) =====
  { v: "Welke onderwerpen komen aan bod in hoofdstuk 8, Randapparatuur?", a: "Toetsenbord, muis, scherm, projector, geluid, netwerken en modems, scanner, printer en stroomvoorziening.", o: "Inhoud" },
  { v: "Welk onderwerp uit de inhoud heeft geen eigen slide in de cursus?", a: "Netwerken en modems.", o: "Inhoud",
    uitleg: "Let op: 'Netwerken en modems' staat in de inhoud, maar er is in deze cursus geen slide over.\n\nGoed om te weten: In deze PDF springen de slidenummers van 3 naar 11: de slides 4 tot 10 zitten er niet in. \"Netwerken en modems\" staat in de inhoud, maar heeft geen eigen slide; daarom staat er verder een korte uitleg zonder slide." },
  { v: "Wat is randapparatuur?", a: "Toestellen rond de computer voor invoer, uitvoer of ondersteuning.", o: "Inhoud",
    uitleg: "- Invoer: toestellen waarmee je iets in de computer brengt, bv. toetsenbord, muis, scanner.\n- Uitvoer: toestellen die iets uit de computer tonen of maken, bv. scherm, projector, printer, luidsprekers.\n- Ondersteuning: bv. de stroomvoorziening en een UPS.\n\nRandapparatuur (in het Engels: peripherals) zijn de toestellen rond de computer zelf. Sommige dienen om iets in te geven (toetsenbord, muis, scanner), andere om iets te tonen of af te drukken (scherm, projector, luidsprekers, printer), en de stroomvoorziening zorgt dat alles blijft werken.\n\nAlle toestellen rond de computer die ermee verbonden zijn (toetsenbord, muis, scherm, printer…). Engels: peripherals." },
  { v: "Welke negen onderwerpen staan in de inhoud?", a: "Toetsenbord, muis, scherm, projector, geluid, netwerken en modems, scanner, printer, stroomvoorziening.", o: "Inhoud",
    uitleg: "Dit hoofdstuk gaat over randapparatuur: de toestellen die je op de computer aansluit (zie Basisbegrippen). Je leert per toestel hoe het werkt en waarop je moet letten. De onderwerpen zijn:\n\nToetsenbord en muis: de belangrijkste invoerapparaten, en het gezondheidsrisico RSI.\n\nScherm en projector: hoe beeld getoond wordt, en wat resolutie en aspect ratio betekenen.\n\nGeluid: de geluidskaart en surround.\n\nNetwerken en modems: om de computer met andere computers en het internet te verbinden.\n\nScanner en printer: papier naar de computer brengen en omgekeerd.\n\nStroomvoorziening: wat er gebeurt als de stroom uitvalt en hoe je je daartegen beschermt." },

  // ===== Toetsenbord (slide 3) =====
  { v: "Wat is het belangrijkste invoerapparaat?", a: "Het toetsenbord.", o: "Toetsenbord",
    uitleg: "Een invoerapparaat is een toestel waarmee je iets in de computer ingeeft.\n\nHet toetsenbord (keyboard) is het belangrijkste invoerapparaat van de computer: hiermee typ je tekst en geef je commando's. Het bestaat al sinds de eerste computers en is afgeleid van de typemachine." },
  { v: "Welke soorten toetsen heeft een toetsenbord?", n: 4, a: "Alfabetische en numerieke tekens, controletoetsen en functietoetsen.", o: "Toetsenbord",
    uitleg: "Toetsenbord: geschiedenis: Verschillende soorten layouts\n\nNumerieke tekens: de cijfers 0 tot 9, bovenaan het toetsenbord en vaak ook rechts op een apart numeriek klavier (numpad), handig om snel getallen in te typen." },
  { v: "Geef de 3 toetsenbordlayouts uit de cursus.", a: "Azerty, Qwerty en Dvorak.", o: "Toetsenbord",
    uitleg: "Goed om te weten: In Windows kies je de layout bij de taalinstellingen. Staat de layout verkeerd (bv. Qwerty terwijl je een Azerty-toetsenbord hebt), dan typ je een \"q\" als je op de A drukt." },
  { v: "Azerty, Qwerty en Dvorak", a: "Azerty gebruiken we in België en Frankrijk; Qwerty gebruiken de meeste andere landen.\n\nDvorak zet de letters die je het vaakst gebruikt op de middelste rij, zodat je sneller en met minder bewegingen kan typen. Weinig mensen gebruiken het.", o: "Toetsenbord", extra: true,
    uitleg: "Dvorak: een layout die ontworpen is om sneller en met minder vermoeidheid te typen. De meest gebruikte letters (o.a. alle klinkers) staan op de middelste rij, waar je vingers rusten. Ze wordt weinig gebruikt." },
  { v: "Waar komt de naam Azerty of Qwerty vandaan, en waarom bestaat de Dvorak-layout?", a: "Azerty en Qwerty: van de eerste letters linksboven op het toetsenbord.\nDvorak: de vaakst gebruikte letters staan op de middelste rij, om sneller te typen.", o: "Toetsenbord",
    uitleg: "Layout = hoe de letters op het toetsenbord verdeeld zijn. In België gebruikt men Azerty, in de meeste andere landen Qwerty.\n\nBij Dvorak hoeven je vingers minder te bewegen, omdat de letters die je het meest typt op de rij liggen waar je vingers in rust staan.\n\nEen layout is de volgorde van de letters op het toetsenbord. De naam komt van de eerste letters linksboven: A-Z-E-R-T-Y of Q-W-E-R-T-Y." },
  { v: "Geef een voorbeeld van een controletoets en van een functietoets.", a: "Controletoets: Ctrl (of Alt, Shift).\nFunctietoets: F1 tot F12.", o: "Toetsenbord",
    uitleg: "Een controletoets gebruik je samen met een andere toets, bv. Ctrl+C om te kopiëren.\n\nDe functietoetsen F1 tot F12 hebben in elk programma een eigen functie, bv. F1 voor hulp, F5 om te vernieuwen.\n\nControletoetsen: toetsen die zelf geen teken typen, maar iets besturen: Ctrl, Alt, Shift, Enter, Esc, Tab, Delete, de pijltjestoetsen… Vaak gebruik je ze in combinatie, bv. Ctrl + C om te kopiëren." },
  { v: "Van welk toestel is het toetsenbord afgeleid?", a: "Van de typemachine.", o: "Toetsenbord", extra: true,
    uitleg: "Het toetsenbord (keyboard) is het belangrijkste invoerapparaat van de computer: hiermee typ je tekst en geef je commando's. Het bestaat al sinds de eerste computers en is afgeleid van de typemachine." },
  { v: "Wat zijn alfabetische tekens?", a: "De letters A tot Z.", o: "Toetsenbord",
    uitleg: "Alfabetische tekens: de letters A tot Z." },
  { v: "Wat zijn numerieke tekens?", a: "De cijfers 0 tot 9.", o: "Toetsenbord",
    uitleg: "Numerieke tekens: de cijfers 0 tot 9, bovenaan het toetsenbord en vaak ook rechts op een apart numeriek klavier (numpad), handig om snel getallen in te typen." },
  { v: "Wat is een numpad?", a: "Een apart numeriek klavier rechts op het toetsenbord.", o: "Toetsenbord", extra: true,
    uitleg: "Numerieke tekens: de cijfers 0 tot 9, bovenaan het toetsenbord en vaak ook rechts op een apart numeriek klavier (numpad), handig om snel getallen in te typen." },
  { v: "Wat zijn controletoetsen? Geef voorbeelden.", a: "Toetsen die iets besturen in plaats van een teken te typen: Ctrl, Alt, Shift, Enter, Esc, Tab, Delete, pijltjes.", o: "Toetsenbord",
    uitleg: "Controletoetsen: toetsen die zelf geen teken typen, maar iets besturen: Ctrl, Alt, Shift, Enter, Esc, Tab, Delete, de pijltjestoetsen… Vaak gebruik je ze in combinatie, bv. Ctrl + C om te kopiëren." },
  { v: "Wat doet Ctrl + C?", a: "Kopiëren.", o: "Toetsenbord",
    uitleg: "Controletoetsen: toetsen die zelf geen teken typen, maar iets besturen: Ctrl, Alt, Shift, Enter, Esc, Tab, Delete, de pijltjestoetsen… Vaak gebruik je ze in combinatie, bv. Ctrl + C om te kopiëren." },
  { v: "Wat zijn functietoetsen?", a: "De toetsen F1 tot F12.", o: "Toetsenbord",
    uitleg: "Functietoetsen: de rij F1 tot F12 bovenaan. Wat ze doen, hangt af van het programma; F1 opent vaak de hulp, F5 vernieuwt een webpagina." },
  { v: "Wat doen F1 en F5 vaak?", a: "F1 opent de hulp, F5 vernieuwt een webpagina.", o: "Toetsenbord", extra: true,
    uitleg: "Functietoetsen: de rij F1 tot F12 bovenaan. Wat ze doen, hangt af van het programma; F1 opent vaak de hulp, F5 vernieuwt een webpagina." },
  { v: "Wat is een toetsenbordlayout?", a: "De manier waarop de letters op het toetsenbord verdeeld zijn.", o: "Toetsenbord", extra: true,
    uitleg: "De layout is de manier waarop de letters op het toetsenbord verdeeld zijn. De naam komt van de eerste zes letters op de bovenste letterrij." },
  { v: "Waar komt de naam van een layout vandaan?", a: "Van de eerste zes letters op de bovenste letterrij.", o: "Toetsenbord",
    uitleg: "De layout is de manier waarop de letters op het toetsenbord verdeeld zijn. De naam komt van de eerste zes letters op de bovenste letterrij." },
  { v: "Welke drie toetsenbordlayouts noemt de cursus?", a: "Azerty, Qwerty en Dvorak.", o: "Toetsenbord",
    uitleg: "Goed om te weten: In Windows kies je de layout bij de taalinstellingen. Staat de layout verkeerd (bv. Qwerty terwijl je een Azerty-toetsenbord hebt), dan typ je een \"q\" als je op de A drukt." },
  { v: "Waar wordt Azerty gebruikt?", a: "In België en Frankrijk.", o: "Toetsenbord", extra: true,
    uitleg: "Azerty: gebruikt in België en Frankrijk. Dit is waarschijnlijk het toetsenbord dat jij gebruikt." },
  { v: "Waar wordt Qwerty gebruikt?", a: "Het meest ter wereld, o.a. in Nederland, de VS en het VK.", o: "Toetsenbord", extra: true,
    uitleg: "Qwerty: de meest gebruikte layout ter wereld, o.a. in Nederland, de VS en het VK. Ze ontstond bij de typemachine: letters die vaak na elkaar komen, staan uit elkaar, zodat de armpjes van de typemachine niet in elkaar haakten." },
  { v: "Waarom staan bij Qwerty vaak samen voorkomende letters uit elkaar?", a: "Zodat de armpjes van de typemachine niet in elkaar haakten.", o: "Toetsenbord", extra: true,
    uitleg: "Qwerty: de meest gebruikte layout ter wereld, o.a. in Nederland, de VS en het VK. Ze ontstond bij de typemachine: letters die vaak na elkaar komen, staan uit elkaar, zodat de armpjes van de typemachine niet in elkaar haakten." },
  { v: "Wat is het doel van Dvorak?", a: "Sneller en met minder vermoeidheid typen.", o: "Toetsenbord", extra: true,
    uitleg: "Dvorak: een layout die ontworpen is om sneller en met minder vermoeidheid te typen. De meest gebruikte letters (o.a. alle klinkers) staan op de middelste rij, waar je vingers rusten. Ze wordt weinig gebruikt." },
  { v: "Hoe zorgt de Dvorak-layout voor sneller typen met minder vermoeidheid?", a: "De meest gebruikte letters (o.a. alle klinkers) staan op de middelste rij.", o: "Toetsenbord", extra: true,
    uitleg: "Dvorak: een layout die ontworpen is om sneller en met minder vermoeidheid te typen. De meest gebruikte letters (o.a. alle klinkers) staan op de middelste rij, waar je vingers rusten. Ze wordt weinig gebruikt." },
  { v: "Welke layout gebruikt men in Duitsland?", a: "Qwertz.", o: "Toetsenbord", extra: true,
    uitleg: "" },
  { v: "Wat gebeurt er als de layout in Windows verkeerd staat?", a: "Je typt andere tekens dan op de toets staan (bv. een q als je op A drukt).", o: "Toetsenbord", extra: true,
    uitleg: "Goed om te weten: In Windows kies je de layout bij de taalinstellingen. Staat de layout verkeerd (bv. Qwerty terwijl je een Azerty-toetsenbord hebt), dan typ je een \"q\" als je op de A drukt.\n\nDe \"…\" betekent dat er nog andere layouts bestaan, bv. Qwertz in Duitsland." },

  // ===== Muis: optische muizen (slide 11) =====
  { v: "Wat heeft een optische muis niet meer?", a: "Roterende onderdelen.", o: "Muis: optische muizen",
    uitleg: "Een optische muis werkt met licht en heeft geen roterende (draaiende) onderdelen meer. Daardoor wordt hij niet vuil vanbinnen, slijt hij minder en is hij veel nauwkeuriger." },
  { v: "Welke lichtbron gebruikt een optische muis?", a: "Een licht-uitstralende diode (LED).", o: "Muis: optische muizen",
    uitleg: "1. Een LED (licht-uitstralende diode) aan de onderkant schijnt licht op het oppervlak (je bureau of muismat). Dat is het rode lichtje dat je onder een muis ziet." },
  { v: "Waar wordt het licht naartoe weerkaatst nadat het op de oppervlakte botst?", a: "Naar een CMOS sensor.", o: "Muis: optische muizen",
    uitleg: "2. Het licht botst op het oppervlak en wordt weerkaatst naar een CMOS-sensor: een piepklein camera'tje in de muis." },
  { v: "Waar zendt de CMOS sensor de weerkaatste \"afbeelding\" naartoe?", a: "Naar een DSP (digital signal processor), voor analyse.", o: "Muis: optische muizen",
    uitleg: "3. De CMOS-sensor maakt zo duizenden kleine \"foto's\" per seconde van het oppervlak en stuurt die \"afbeelding\" naar een DSP (digital signal processor): een chip die gespecialiseerd is in het snel analyseren van signalen." },
  { v: "Waarvoor staat DSP?", a: "Digital signal processor.", o: "Muis: optische muizen",
    uitleg: "3. De CMOS-sensor maakt zo duizenden kleine \"foto's\" per seconde van het oppervlak en stuurt die \"afbeelding\" naar een DSP (digital signal processor): een chip die gespecialiseerd is in het snel analyseren van signalen." },
  { v: "Wat doet de DSP in een optische muis?", a: "Hij herkent patronen en hoe een patroon is verplaatst tegenover het vorige patroon.", o: "Muis: optische muizen",
    uitleg: "4. De DSP herkent patronen in de foto (kleine oneffenheden en vezels in het oppervlak) en berekent hoe het patroon verschoven is tegenover de vorige foto. Schuift het patroon naar links, dan beweeg je de muis naar rechts. Die beweging stuurt de muis naar de computer, die de cursor verplaatst." },
  { v: "Beschrijf de werking van een optische muis in 4 stappen.", a: "1. Een licht-uitstralende diode (LED) geeft licht.\n2. Het licht botst op de oppervlakte en wordt weerkaatst naar een CMOS sensor.\n3. De CMOS sensor zendt de weerkaatste \"afbeelding\" naar een DSP voor analyse.\n4. De DSP herkent patronen en hoe een patroon is verplaatst tegenover het vorige patroon.", o: "Muis: optische muizen", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s11_optische_muis.jpg" },
  { v: "Wat toont deze foto van een muis?", a: "De onderkant van een optische muis, met het licht van de LED.", o: "Muis: optische muizen", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s11_optische_muis.jpg",
    uitleg: "Wat zie je op de afbeelding? De foto toont de onderkant van een optische muis van heel dichtbij, fel rood verlicht. In het midden zie je een ovale opening; daardoor schijnt het rode LED-licht naar buiten, en het weerkaatste licht komt erdoor terug naar de sensor. In het midden van die opening zie je een klein glanzend lensje." },
  { v: "Optische muis op glas", a: "Een optische muis werkt slecht op glas of een spiegel: daar ziet de sensor geen patroon om te vergelijken. Een muismat of een tafel met wat structuur werkt het best.", o: "Muis: optische muizen", extra: true,
    uitleg: "Daarom werkt een optische muis slecht op glas of een spiegel: daar zijn geen patronen te zien." },
  { v: "Waar wordt het weerkaatste licht in een optische muis naartoe gestuurd, en waarom werkt zo'n muis slecht op glas of een spiegel?", a: "Naar een CMOS-sensor.\nOp glas of een spiegel ziet de sensor geen patroon, dus kan hij geen beweging meten.", o: "Muis: optische muizen",
    uitleg: "Een led schijnt op de ondergrond. De CMOS-sensor maakt heel snel kleine foto's van die ondergrond. Door de foto's te vergelijken, ziet de muis in welke richting en hoe ver ze bewogen is.\n\nOp een doorzichtig of spiegelend oppervlak zijn er geen herkenbare puntjes om te vergelijken.\n\nEen optische muis werkt met licht, zoals een heel kleine camera:\n1. Een LED schijnt licht op de tafel.\n2. Het licht weerkaatst naar een CMOS-sensor; die maakt er een klein beeldje van.\n3. Dat beeldje gaat naar een DSP, een chip die beelden analyseert.\n4. De DSP vergelijkt elk beeldje met het vorige. Zo weet hij in welke richting en hoe ver je de muis bewogen hebt." },
  { v: "Waarom is een optische muis beter dan een oude muis met een bal?", a: "Ze heeft geen roterende onderdelen meer die vuil worden.", o: "Muis: optische muizen",
    uitleg: "Een oude muis had een rubberen bal met rolletjes erin. Stof en vuil kwamen op de rolletjes, waardoor de cursor schokkerig bewoog en je de muis moest schoonmaken.\n\nEen optische muis heeft geen bewegende delen aan de onderkant.\n\nOudere muizen hadden onderaan een bal met rolletjes die meedraaiden (roterende onderdelen). Die werden vuil en haperden." },
  { v: "Wat doet een muis?", a: "Een cursor over het scherm bewegen en op dingen klikken.", o: "Muis: optische muizen", extra: true,
    uitleg: "De muis is een invoerapparaat waarmee je een pijltje (de cursor) over het scherm beweegt en op dingen klikt. Vroeger had een muis vanonder een rubberen balletje dat rolde en wieltjes in de muis liet draaien (een mechanische muis). Die raakte vuil en moest geregeld gekuist worden." },
  { v: "Hoe werkte een mechanische muis?", a: "Met een rubberen balletje dat wieltjes in de muis liet draaien.", o: "Muis: optische muizen", extra: true,
    uitleg: "De muis is een invoerapparaat waarmee je een pijltje (de cursor) over het scherm beweegt en op dingen klikt. Vroeger had een muis vanonder een rubberen balletje dat rolde en wieltjes in de muis liet draaien (een mechanische muis). Die raakte vuil en moest geregeld gekuist worden." },
  { v: "Wat was het nadeel van een mechanische muis?", a: "Ze werd vuil en moest gekuist worden.", o: "Muis: optische muizen", extra: true,
    uitleg: "De muis is een invoerapparaat waarmee je een pijltje (de cursor) over het scherm beweegt en op dingen klikt. Vroeger had een muis vanonder een rubberen balletje dat rolde en wieltjes in de muis liet draaien (een mechanische muis). Die raakte vuil en moest geregeld gekuist worden." },
  { v: "Wat is het grote verschil tussen een optische en een mechanische muis?", a: "Geen roterende onderdelen meer.", o: "Muis: optische muizen",
    uitleg: "Een optische muis werkt met licht en heeft geen roterende (draaiende) onderdelen meer. Daardoor wordt hij niet vuil vanbinnen, slijt hij minder en is hij veel nauwkeuriger." },
  { v: "Wat zijn de voordelen van een muis zonder roterende onderdelen?", a: "Niet vuil vanbinnen, minder slijtage, nauwkeuriger.", o: "Muis: optische muizen", extra: true,
    uitleg: "Een optische muis werkt met licht en heeft geen roterende (draaiende) onderdelen meer. Daardoor wordt hij niet vuil vanbinnen, slijt hij minder en is hij veel nauwkeuriger." },
  { v: "Optische muis, stap 1: wat doet de LED?", a: "Ze schijnt licht op het oppervlak.", o: "Muis: optische muizen",
    uitleg: "1. Een LED (licht-uitstralende diode) aan de onderkant schijnt licht op het oppervlak (je bureau of muismat). Dat is het rode lichtje dat je onder een muis ziet." },
  { v: "Optische muis, stap 2: wat gebeurt er met het licht?", a: "Het botst op het oppervlak en wordt weerkaatst naar een CMOS-sensor.", o: "Muis: optische muizen",
    uitleg: "2. Het licht botst op het oppervlak en wordt weerkaatst naar een CMOS-sensor: een piepklein camera'tje in de muis." },
  { v: "Optische muis, stap 3: wat doet de CMOS-sensor?", a: "Ze maakt duizenden \"foto's\" per seconde en stuurt die naar een DSP.", o: "Muis: optische muizen",
    uitleg: "3. De CMOS-sensor maakt zo duizenden kleine \"foto's\" per seconde van het oppervlak en stuurt die \"afbeelding\" naar een DSP (digital signal processor): een chip die gespecialiseerd is in het snel analyseren van signalen." },
  { v: "Optische muis, stap 4: wat doet de DSP?", a: "Hij herkent patronen en berekent hoe het patroon verplaatst is tegenover het vorige.", o: "Muis: optische muizen",
    uitleg: "4. De DSP herkent patronen in de foto (kleine oneffenheden en vezels in het oppervlak) en berekent hoe het patroon verschoven is tegenover de vorige foto. Schuift het patroon naar links, dan beweeg je de muis naar rechts. Die beweging stuurt de muis naar de computer, die de cursor verplaatst." },
  { v: "Waarom werkt een optische muis slecht op glas?", a: "Er zijn geen patronen te zien.", o: "Muis: optische muizen",
    uitleg: "Daarom werkt een optische muis slecht op glas of een spiegel: daar zijn geen patronen te zien." },
  { v: "Wat toont de foto bij de optische muis?", a: "De rood verlichte onderkant van een optische muis met de ovale opening en het lensje.", o: "Muis: optische muizen", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s11_optische_muis.jpg",
    uitleg: "Wat zie je op de afbeelding? De foto toont de onderkant van een optische muis van heel dichtbij, fel rood verlicht. In het midden zie je een ovale opening; daardoor schijnt het rode LED-licht naar buiten, en het weerkaatste licht komt erdoor terug naar de sensor. In het midden van die opening zie je een klein glanzend lensje." },

  // ===== Muis: RSI (slide 12) =====
  { v: "Waarvoor staat RSI?", a: "Repetitive Strain Injury.", o: "Muis: RSI",
    uitleg: "RSI staat voor Repetitive Strain Injury: letsel door herhaalde belasting. Het zijn klachten aan de handen, polsen, armen, nek en schouders (pijn, tintelingen, stijfheid, krachtverlies) die ontstaan doordat je telkens dezelfde kleine beweging herhaalt, vaak in een slechte houding. Bij computerwerk komt dat door urenlang typen en met de muis werken." },
  { v: "Hoeveel studenten hebben last van RSI volgens de cursus?", a: "50% van de tweedejaarsstudenten en 66% van de derdejaarsstudenten.", o: "Muis: RSI",
    uitleg: "De slide geeft cijfers: 50% van de tweedejaarsstudenten en 66% (twee derde) van de derdejaarsstudenten heeft er last van. Het neemt dus toe naarmate je langer achter de computer studeert. Het is een probleem dat jou als IT-student rechtstreeks aangaat." },
  { v: "Geef de 4 voorzorgen tegen RSI.", a: "1. Regelmatig breaks nemen.\n2. Typen, niet rammen.\n3. Aangepaste hardware.\n4. Een goede houding gebruiken.", o: "Muis: RSI", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s12_rsi_pols.jpg",
    uitleg: "Regelmatig breaks nemen, typen niet rammen, aangepaste hardware, goede houding." },
  { v: "Wat betekent de voorzorg 'typen, niet rammen'?", a: "Niet te hard op de toetsen slaan.", o: "Muis: RSI",
    uitleg: "Typen, niet rammen: druk de toetsen zacht in, sla er niet hard op. Hard rammen belast je vingers en polsen onnodig." },
  { v: "Welke klacht toont deze foto?", a: "RSI (Repetitive Strain Injury): pijn in de pols door veel typen.", o: "Muis: RSI", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s12_rsi_pols.jpg",
    uitleg: "Op de foto houdt iemand zijn pijnlijke pols vast boven een toetsenbord.\n\nRSI staat voor Repetitive Strain Injury: letsel door herhaalde belasting. Het zijn klachten aan de handen, polsen, armen, nek en schouders (pijn, tintelingen, stijfheid, krachtverlies) die ontstaan doordat je telkens dezelfde kleine beweging herhaalt, vaak in een slechte houding. Bij computerwerk komt dat door urenlang typen en met de muis werken." },
  { v: "Wat is RSI, waar kan je klachten krijgen, en geef een voorbeeld van aangepaste hardware ertegen.", a: "RSI: klachten door steeds dezelfde beweging te herhalen.\nKlachten aan pols, arm, nek of schouders.\nAangepaste hardware: een ergonomische of verticale muis, een polssteun, een gesplitst toetsenbord.", o: "Muis: RSI",
    uitleg: "RSI = Repetitive Strain Injury: letsel door herhaalde belasting. De cursus zegt dat 50% van de tweedejaarsstudenten en 66% van de derdejaarsstudenten er last van hebben.\n\nBij een verticale muis staat je hand rechtop, zodat je onderarm niet gedraaid hoeft te worden.\n\nRSI zijn klachten (pijn, tintelingen, stijfheid) in pols, arm, nek of schouders. Je krijgt ze door heel vaak dezelfde kleine beweging te herhalen, zoals typen en klikken. Repetitive = herhalend, strain = belasting, injury = letsel." },
  { v: "Wat betekent RSI?", a: "Letsel door herhaalde belasting.", o: "Muis: RSI",
    uitleg: "RSI staat voor Repetitive Strain Injury: letsel door herhaalde belasting. Het zijn klachten aan de handen, polsen, armen, nek en schouders (pijn, tintelingen, stijfheid, krachtverlies) die ontstaan doordat je telkens dezelfde kleine beweging herhaalt, vaak in een slechte houding. Bij computerwerk komt dat door urenlang typen en met de muis werken.\n\nGoede houding gebruiken: zie de volgende slide." },
  { v: "Waar heb je last bij RSI?", a: "Handen, polsen, armen, nek en schouders.", o: "Muis: RSI", extra: true,
    uitleg: "RSI staat voor Repetitive Strain Injury: letsel door herhaalde belasting. Het zijn klachten aan de handen, polsen, armen, nek en schouders (pijn, tintelingen, stijfheid, krachtverlies) die ontstaan doordat je telkens dezelfde kleine beweging herhaalt, vaak in een slechte houding. Bij computerwerk komt dat door urenlang typen en met de muis werken." },
  { v: "Welke klachten geeft RSI?", a: "Pijn, tintelingen, stijfheid, krachtverlies.", o: "Muis: RSI",
    uitleg: "RSI staat voor Repetitive Strain Injury: letsel door herhaalde belasting. Het zijn klachten aan de handen, polsen, armen, nek en schouders (pijn, tintelingen, stijfheid, krachtverlies) die ontstaan doordat je telkens dezelfde kleine beweging herhaalt, vaak in een slechte houding. Bij computerwerk komt dat door urenlang typen en met de muis werken." },
  { v: "Hoeveel derdejaarsstudenten hebben last van RSI?", a: "66% (twee derde).", o: "Muis: RSI",
    uitleg: "De slide geeft cijfers: 50% van de tweedejaarsstudenten en 66% (twee derde) van de derdejaarsstudenten heeft er last van. Het neemt dus toe naarmate je langer achter de computer studeert. Het is een probleem dat jou als IT-student rechtstreeks aangaat." },
  { v: "Hoe vaak neem je best een break?", a: "Elke 30 tot 60 minuten.", o: "Muis: RSI", extra: true,
    uitleg: "Regelmatig breaks nemen: elke 30 tot 60 minuten even rechtstaan, rondlopen en je handen en schouders losmaken. Zo krijgen je spieren rust." },
  { v: "Wat betekent \"typen, niet rammen\"?", a: "Toetsen zacht indrukken, niet hard erop slaan.", o: "Muis: RSI",
    uitleg: "Typen, niet rammen: druk de toetsen zacht in, sla er niet hard op. Hard rammen belast je vingers en polsen onnodig." },
  { v: "Geef voorbeelden van aangepaste hardware.", a: "Ergonomische (verticale) muis, ergonomisch toetsenbord, polssteun.", o: "Muis: RSI", extra: true,
    uitleg: "Aangepaste hardware: bv. een ergonomische muis (een verticale muis waarbij je hand rechtop staat, zoals bij een handdruk), een ergonomisch toetsenbord, of een polssteun." },
  { v: "Wat toont de foto bij RSI?", a: "Een hand op een toetsenbord met een rood gekleurde pols (de pijnplek).", o: "Muis: RSI", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s12_rsi_pols.jpg",
    uitleg: "Wat zie je op de afbeelding? Onderaan een foto van een hand die op een wit toetsenbord ligt. De pols is rood gekleurd: dat toont waar de pijn bij RSI vaak zit." },

  // ===== Muis: RSI, de ideale beeldschermwerkplek (slide 13) =====
  { v: "Welke maten horen op plaats 1 tot 7 van de ideale beeldschermwerkplek?", a: "1. min. 50 cm (afstand ogen – scherm)\n2. ±30° (kijkhoek naar het scherm)\n3. ≥90° (ellebogen)\n4. ≥90° (knieën)\n5. instelbaar 39 - 51 cm (zithoogte)\n6. instelbaar 62 - 82 cm, vast 74 - 76 cm (bureauhoogte)\n7. min. 80 cm (beenruimte)", o: "Muis: RSI, de ideale beeldschermwerkplek", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s13_werkplek_vraag.jpg", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s13_werkplek.jpg",
    uitleg: "Instelbaar = je kan de hoogte aanpassen; vast = de hoogte ligt vast." },
  { v: "Hoe ver staat het scherm minstens van je ogen op de ideale werkplek?", a: "Minstens 50 cm.", o: "Muis: RSI, de ideale beeldschermwerkplek",
    uitleg: "• Afstand ogen–scherm: minimaal 50 cm. Zo moeten je ogen niet te hard werken." },
  { v: "Onder welke hoek kijk je naar het scherm op de ideale werkplek?", a: "±30° (ongeveer 30°) naar beneden.", o: "Muis: RSI, de ideale beeldschermwerkplek", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s13_werkplek.jpg",
    uitleg: "• Kijkhoek: ongeveer 30° naar beneden (±30°). De bovenkant van het scherm staat op of net onder ooghoogte, zodat je je nek niet naar boven moet buigen." },
  { v: "Welke hoek maken je ellebogen en je knieën op de ideale werkplek?", a: "≥90° (90° of meer).", o: "Muis: RSI, de ideale beeldschermwerkplek",
    uitleg: "• Ellebogen: hoek van minstens 90° (≥90°). Je bovenarmen hangen ontspannen naast je lichaam, je onderarmen liggen horizontaal." },
  { v: "Hoe hoog is de zitting op de ideale werkplek?", a: "Instelbaar tussen 39 en 51 cm.", o: "Muis: RSI, de ideale beeldschermwerkplek",
    uitleg: "• Zithoogte stoel: instelbaar van 39 tot 51 cm, zodat elke lengte past." },
  { v: "Hoe hoog is het bureau op de ideale werkplek?", a: "Instelbaar 62 - 82 cm, of vast 74 - 76 cm.", o: "Muis: RSI, de ideale beeldschermwerkplek",
    uitleg: "• Bureauhoogte: instelbaar 62 tot 82 cm, of bij een vast bureau 74 tot 76 cm." },
  { v: "Hoeveel beenruimte is er minstens onder het bureau op de ideale werkplek?", a: "Minstens 80 cm.", o: "Muis: RSI, de ideale beeldschermwerkplek",
    uitleg: "• Beenruimte onder het bureau: minimaal 80 cm diep." },
  { v: "Waar staat de bovenrand van het scherm op de ideale werkplek, en hoe staan je voeten?", a: "De bovenrand van het scherm staat ongeveer op ooghoogte.\nJe voeten staan plat op de grond.", o: "Muis: RSI, de ideale beeldschermwerkplek",
    uitleg: "Zo kijk je een beetje naar beneden naar het scherm, en hoef je je nek niet op te tillen of te buigen.\n\nVoeten plat op de grond: je zit stabiel en je bovenbenen zijn ongeveer horizontaal. Raken je voeten de grond niet, dan gebruik je een voetsteun.\n\nZo zit je goed om RSI te voorkomen.\n\n±30° = ongeveer 30°: je kijkt een beetje naar beneden naar het scherm, niet recht vooruit en niet omhoog.\n≥90° = 90° of meer: je armen en knieën zijn niet scherper geplooid dan een rechte hoek." },
  { v: "Hoe heet deze tekening?", a: "De ideale beeldschermwerkplek.", o: "Muis: RSI, de ideale beeldschermwerkplek", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s13_werkplek_vraag.jpg", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s13_werkplek.jpg",
    uitleg: "Deze slide toont met een tekening hoe een goede werkhouding aan een computer eruitziet. De titel onderaan is \"De ideale beeldschermwerkplek\". Een goede houding is een van de belangrijkste manieren om RSI te voorkomen." },
  { v: "Waar staat de bovenkant van het scherm op de ideale beeldschermwerkplek?", a: "Op of net onder ooghoogte.", o: "Muis: RSI, de ideale beeldschermwerkplek", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s13_werkplek.jpg",
    uitleg: "• Kijkhoek: ongeveer 30° naar beneden (±30°). De bovenkant van het scherm staat op of net onder ooghoogte, zodat je je nek niet naar boven moet buigen.\n\nWat zie je op de afbeelding? Je ziet een zijaanzicht van een persoon op een bureaustoel aan een bureau met een scherm, toetsenbord en voetsteun. Rode lijnen en pijlen tonen de maten:\n\nKortom: je zit rechtop met steun in de rug, je voeten plat, ellebogen en knieën ongeveer in een rechte hoek, en het scherm op armlengte iets onder ooghoogte." },
  { v: "Welke hoek maken de ellebogen op de ideale beeldschermwerkplek?", a: "Minstens 90°.", o: "Muis: RSI, de ideale beeldschermwerkplek", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s13_werkplek.jpg",
    uitleg: "• Ellebogen: hoek van minstens 90° (≥90°). Je bovenarmen hangen ontspannen naast je lichaam, je onderarmen liggen horizontaal." },
  { v: "Welke hoek maken de knieën op de ideale beeldschermwerkplek?", a: "Minstens 90°.", o: "Muis: RSI, de ideale beeldschermwerkplek", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s13_werkplek.jpg",
    uitleg: "• Knieën: hoek van minstens 90° (≥90°). Je dijen zijn ongeveer horizontaal." },
  { v: "Hoe hoog is een instelbare stoel op de ideale beeldschermwerkplek?", a: "39 tot 51 cm.", o: "Muis: RSI, de ideale beeldschermwerkplek", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s13_werkplek.jpg",
    uitleg: "• Zithoogte stoel: instelbaar van 39 tot 51 cm, zodat elke lengte past.\n\n• De rugleuning van de stoel steunt de onderrug." },
  { v: "Hoe hoog is een instelbaar bureau op de ideale beeldschermwerkplek?", a: "62 tot 82 cm.", o: "Muis: RSI, de ideale beeldschermwerkplek", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s13_werkplek.jpg",
    uitleg: "• Bureauhoogte: instelbaar 62 tot 82 cm, of bij een vast bureau 74 tot 76 cm." },
  { v: "Hoe hoog is een vast bureau op de ideale beeldschermwerkplek?", a: "74 tot 76 cm.", o: "Muis: RSI, de ideale beeldschermwerkplek", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s13_werkplek.jpg",
    uitleg: "• Bureauhoogte: instelbaar 62 tot 82 cm, of bij een vast bureau 74 tot 76 cm." },
  { v: "Waarvoor dient de voetsteun op de ideale beeldschermwerkplek?", a: "Voor als je voeten niet plat op de grond komen.", o: "Muis: RSI, de ideale beeldschermwerkplek", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s13_werkplek.jpg",
    uitleg: "• Onder de voeten staat een voetsteun, voor als je voeten niet plat op de grond komen." },

  // ===== Scherm: verschillende varianten (slide 14) =====
  { v: "Welke 3 varianten van schermen bespreekt de cursus?", a: "CRT, LCD en projectie.", o: "Scherm: verschillende varianten" },
  { v: "Geef de 3 kenmerken van een CRT-scherm.", a: "Zo goed als compleet van de markt verdwenen, groot en hoog stroomverbruik.", o: "Scherm: verschillende varianten",
    uitleg: "Zo goed als compleet van de markt verdwenen." },
  { v: "Geef de 3 kenmerken van een LCD-scherm.", a: "Markt bijna volledig overgenomen, smal en laag stroomverbruik.", o: "Scherm: verschillende varianten",
    uitleg: "Heeft de markt bijna volledig overgenomen." },
  { v: "Welk schermtype is zo goed als compleet van de markt verdwenen?", a: "CRT.", o: "Scherm: verschillende varianten",
    uitleg: "Zo goed als compleet van de markt verdwenen." },
  { v: "Welk schermtype heeft de markt bijna volledig overgenomen?", a: "LCD.", o: "Scherm: verschillende varianten",
    uitleg: "Heeft de markt bijna volledig overgenomen." },
  { v: "Welk schermtype heeft een hoog stroomverbruik: CRT of LCD?", a: "CRT. (LCD heeft een laag stroomverbruik.)", o: "Scherm: verschillende varianten" },
  { v: "Geef de 2 punten over projectie uit de cursus.", a: "Lumen en de hoge kostprijs om de lamp te vervangen.", o: "Scherm: verschillende varianten",
    uitleg: "Hoge kostprijs vervanging lamp: de lamp van een klassieke projector gaat maar een paar duizend uur mee en is duur om te vervangen." },
  { v: "Wat drukt lumen uit bij projectie?", a: "Hoe fel het licht is: hoe meer lumen, hoe helderder het beeld.", o: "Scherm: verschillende varianten",
    uitleg: "Bij projectie werpt een projector (beamer) het beeld op een muur of doek. Lumen is de eenheid waarin je uitdrukt hoe fel het licht van een projector is: hoe meer lumen, hoe helderder het beeld. De lamp van een projector slijt en is duur om te vervangen." },
  { v: "CRT en LCD voluit", a: "CRT = Cathode Ray Tube (beeldbuis). Een elektronenstraal tekent het beeld op het glas; daarom is het scherm zo diep.\nLCD = Liquid Crystal Display (scherm met vloeibare kristallen).", o: "Scherm: verschillende varianten", extra: true,
    uitleg: "LCD staat voor Liquid Crystal Display: een scherm met vloeibare kristallen. Achter het scherm zit een lamp (tegenwoordig LED-verlichting). De kristallen werken als minuscule luikjes die per pixel meer of minder licht doorlaten, met rode, groene en blauwe filters voor de kleur. Dit is het platte scherm (flatscreen) dat je nu overal ziet." },
  { v: "Waarvoor staan CRT en LCD, en waarom is een CRT-scherm zo diep?", a: "CRT: Cathode Ray Tube (beeldbuis).\nLCD: Liquid Crystal Display.\nIn een CRT tekent een elektronenstraal vanuit de beeldbuis het beeld op het glazen scherm. Die straal heeft afstand nodig.", o: "Scherm: verschillende varianten",
    uitleg: "Een CRT-scherm is het oude, diepe scherm. Achteraan zit een elektronenkanon, dat de straal over het scherm laat bewegen.\n\nEen LCD-scherm is plat: vloeibare kristallen laten per pixel meer of minder licht door van een achtergrondverlichting.\n\nCRT is het oude, diepe scherm met een beeldbuis (zoals oude televisies). LCD is het platte scherm dat je nu overal ziet." },
  { v: "Wat is lumen bij een projector?", a: "De eenheid van lichtsterkte (helderheid).", o: "Scherm: verschillende varianten",
    uitleg: "Hoe meer lumen, hoe helderder het beeld. In een lichte ruimte heb je een projector met meer lumen nodig, anders zie je het beeld slecht.\n\nDe helderheid van een projector wordt uitgedrukt in lumen: de hoeveelheid licht die hij uitstraalt. Hoe meer lumen, hoe beter je het beeld ziet in een lichte ruimte. Voor een klaslokaal heb je er al gauw 3000 of meer nodig." },
  { v: "Welke drie schermvarianten noemt de cursus?", a: "CRT, LCD en projectie.", o: "Scherm: verschillende varianten",
    uitleg: "Het scherm (monitor, display) is het belangrijkste uitvoerapparaat: het toont je wat de computer doet. De slide bespreekt drie varianten.\n\nGroot: diep en zwaar, door de buis.\n\nHoog stroomverbruik.\n\nSmal: het is dun en licht.\n\nLaag stroomverbruik." },
  { v: "Waar staat CRT voor?", a: "Cathode Ray Tube (kathodestraalbuis).", o: "Scherm: verschillende varianten", extra: true,
    uitleg: "CRT staat voor Cathode Ray Tube (kathodestraalbuis): het oude, diepe \"bolle\" scherm, zoals de oude televisies. Achteraan in een glazen buis schiet een elektronenstraal naar de voorkant, waar hij kleurstofjes doet oplichten." },
  { v: "Hoe werkt een CRT kort?", a: "Een elektronenstraal in een glazen buis doet kleurstofjes aan de voorkant oplichten.", o: "Scherm: verschillende varianten", extra: true,
    uitleg: "CRT staat voor Cathode Ray Tube (kathodestraalbuis): het oude, diepe \"bolle\" scherm, zoals de oude televisies. Achteraan in een glazen buis schiet een elektronenstraal naar de voorkant, waar hij kleurstofjes doet oplichten." },
  { v: "Waar staat LCD voor?", a: "Liquid Crystal Display.", o: "Scherm: verschillende varianten",
    uitleg: "LCD staat voor Liquid Crystal Display: een scherm met vloeibare kristallen. Achter het scherm zit een lamp (tegenwoordig LED-verlichting). De kristallen werken als minuscule luikjes die per pixel meer of minder licht doorlaten, met rode, groene en blauwe filters voor de kleur. Dit is het platte scherm (flatscreen) dat je nu overal ziet." },
  { v: "Hoe werkt een LCD kort?", a: "Vloeibare kristallen laten per pixel meer of minder licht door van een lamp (LED) erachter, met kleurfilters.", o: "Scherm: verschillende varianten", extra: true,
    uitleg: "LCD staat voor Liquid Crystal Display: een scherm met vloeibare kristallen. Achter het scherm zit een lamp (tegenwoordig LED-verlichting). De kristallen werken als minuscule luikjes die per pixel meer of minder licht doorlaten, met rode, groene en blauwe filters voor de kleur. Dit is het platte scherm (flatscreen) dat je nu overal ziet." },
  { v: "Waarin druk je de helderheid van een projector uit?", a: "In lumen.", o: "Scherm: verschillende varianten",
    uitleg: "De helderheid van een projector wordt uitgedrukt in lumen: de hoeveelheid licht die hij uitstraalt. Hoe meer lumen, hoe beter je het beeld ziet in een lichte ruimte. Voor een klaslokaal heb je er al gauw 3000 of meer nodig.\n\nBij projectie wordt het beeld met een projector (beamer) op een muur of doek geworpen (zie verder)." },
  { v: "Wat betekent meer lumen?", a: "Meer licht, dus een beter zichtbaar beeld in een lichte ruimte.", o: "Scherm: verschillende varianten", extra: true,
    uitleg: "De helderheid van een projector wordt uitgedrukt in lumen: de hoeveelheid licht die hij uitstraalt. Hoe meer lumen, hoe beter je het beeld ziet in een lichte ruimte. Voor een klaslokaal heb je er al gauw 3000 of meer nodig." },
  { v: "Wat is het nadeel van een klassieke projector?", a: "Hoge kostprijs om de lamp te vervangen.", o: "Scherm: verschillende varianten",
    uitleg: "Hoge kostprijs vervanging lamp: de lamp van een klassieke projector gaat maar een paar duizend uur mee en is duur om te vervangen." },

  // ===== Scherm: eigenschappen (slide 15) =====
  { v: "Welke 2 paren eigenschappen van schermen bespreekt de cursus?", a: "Schermgrootte en aspect ratio, en resolutie en dot pitch.", o: "Scherm: eigenschappen", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s15_lcd_scherm.jpg" },
  { v: "Wat is de aspect ratio van een scherm?", a: "De verhouding tussen de breedte en de hoogte van het scherm.", o: "Scherm: eigenschappen",
    uitleg: "De aspect ratio is de verhouding tussen de breedte en de hoogte van het scherm. 4:3 is bijna vierkant (oude schermen), 16:9 is breedbeeld (tv's en de meeste schermen), 16:10 is iets hoger dan 16:9.\n\nDe aspect ratio (beeldverhouding) is de verhouding tussen de breedte en de hoogte van het scherm." },
  { v: "Geef de 3 aspect ratio's uit de cursus.", a: "4:3, 16:9 en 16:10.", o: "Scherm: eigenschappen",
    uitleg: "De aspect ratio (beeldverhouding) is de verhouding tussen de breedte en de hoogte van het scherm." },
  { v: "Wat is de resolutie van een scherm?", a: "Hoeveel aanstuurbare kleurstippen (pixels) het scherm heeft.", o: "Scherm: eigenschappen",
    uitleg: "De resolutie zegt hoeveel aanstuurbare kleurstippen (pixels) het scherm heeft (zie Basisbegrippen). \"Aanstuurbaar\" betekent dat de computer elke pixel apart een kleur kan geven. Voorbeelden van de slide: 1024×768 (een oude resolutie bij 4:3) en 1600×1200 (ook 4:3). Hoe hoger de resolutie, hoe scherper en gedetailleerder het beeld." },
  { v: "Geef de 2 voorbeelden van resoluties uit de cursus.", a: "1024x768 en 1600x1200.", o: "Scherm: eigenschappen" },
  { v: "Wat is de dot pitch?", a: "De plaats (afstand) tussen 2 pixels.", o: "Scherm: eigenschappen",
    uitleg: "De dot pitch is de afstand tussen 2 pixels. Hoe kleiner die afstand, hoe dichter de pixels bij elkaar staan en hoe scherper het beeld.\n\nDe dot pitch is de afstand tussen 2 pixels (meestal in millimeter). Hoe kleiner, hoe beter: de pixels staan dichter bij elkaar, dus je ziet ze minder en het beeld lijkt scherper. Daarom kan een klein scherm met dezelfde resolutie scherper ogen dan een groot scherm." },
  { v: "Is een kleine of een grote dot pitch beter?", a: "Hoe kleiner, hoe beter.", o: "Scherm: eigenschappen",
    uitleg: "De dot pitch is de afstand tussen 2 pixels (meestal in millimeter). Hoe kleiner, hoe beter: de pixels staan dichter bij elkaar, dus je ziet ze minder en het beeld lijkt scherper. Daarom kan een klein scherm met dezelfde resolutie scherper ogen dan een groot scherm." },
  { v: "Wat betekent 1024x768?", a: "1024 pixels in de breedte en 768 pixels in de hoogte.", o: "Scherm: eigenschappen",
    uitleg: "Een pixel is één kleurstipje op het scherm. De resolutie zegt hoeveel pixels er zijn: 1024x768 = 1024 pixels breed en 768 pixels hoog.\n\nDe resolutie zegt hoeveel aanstuurbare kleurstippen (pixels) het scherm heeft (zie Basisbegrippen). \"Aanstuurbaar\" betekent dat de computer elke pixel apart een kleur kan geven. Voorbeelden van de slide: 1024×768 (een oude resolutie bij 4:3) en 1600×1200 (ook 4:3). Hoe hoger de resolutie, hoe scherper en gedetailleerder het beeld." },
  { v: "Welk soort scherm zie je op deze foto?", a: "Een LCD-scherm (plat scherm).", o: "Scherm: eigenschappen", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s15_lcd_scherm.jpg",
    uitleg: "Wat zie je op de afbeelding? Rechts een foto van een plat LCD-scherm (een zilvergrijs computerscherm op een voet) met een blauw beeld." },
  { v: "Schermgrootte", a: "De schermgrootte meet je schuin, van hoek tot hoek (de diagonaal), in inch. 1 inch = 2,54 cm. Een scherm van 24 inch is dus ongeveer 61 cm schuin gemeten.", o: "Scherm: eigenschappen", extra: true,
    uitleg: "De schermgrootte wordt gemeten diagonaal: van de linkeronderhoek naar de rechterbovenhoek van het zichtbare beeld, meestal in inch (duim, 1 inch = 2,54 cm). Een scherm van 24 inch heeft dus een diagonaal van ongeveer 61 cm." },
  { v: "Hoe meet je de schermgrootte?", a: "Diagonaal, in inch (1 inch = 2,54 cm).", o: "Scherm: eigenschappen",
    uitleg: "Je meet van de ene hoek naar de schuin tegenoverliggende hoek, bv. van linksonder naar rechtsboven. Een scherm van 24 inch is dus 24 × 2,54 = ongeveer 61 cm diagonaal.\n\nDe schermgrootte wordt gemeten diagonaal: van de linkeronderhoek naar de rechterbovenhoek van het zichtbare beeld, meestal in inch (duim, 1 inch = 2,54 cm). Een scherm van 24 inch heeft dus een diagonaal van ongeveer 61 cm.\n\nDiagonaal, in inch." },
  { v: "Hoeveel cm is 1 inch?", a: "2,54 cm.", o: "Scherm: eigenschappen", extra: true,
    uitleg: "De schermgrootte wordt gemeten diagonaal: van de linkeronderhoek naar de rechterbovenhoek van het zichtbare beeld, meestal in inch (duim, 1 inch = 2,54 cm). Een scherm van 24 inch heeft dus een diagonaal van ongeveer 61 cm." },
  { v: "Wat is 4:3 en waar vond je het?", a: "Bijna vierkant; oude CRT-schermen en tv's.", o: "Scherm: eigenschappen", extra: true,
    uitleg: "4:3: voor elke 4 eenheden breed 3 eenheden hoog. Bijna vierkant; de oude CRT-schermen en oude tv's." },
  { v: "Wat is 16:9 en waar vind je het?", a: "Breedbeeld; tv's, films en de meeste monitors.", o: "Scherm: eigenschappen", extra: true,
    uitleg: "16:9: breedbeeld. De standaard voor tv's, films en de meeste monitors vandaag (bv. 1920×1080)." },
  { v: "Wat is 16:10 en waarom is het handig?", a: "Iets hoger dan 16:9; je ziet meer tekstregels.", o: "Scherm: eigenschappen", extra: true,
    uitleg: "16:10: iets hoger dan 16:9, handig om meer tekstregels te zien. Vaak bij laptops en werkmonitors (bv. 1920×1200)." },
  { v: "Wat betekent 'aanstuurbare kleurstippen' bij de resolutie van een scherm?", a: "De computer kan elke pixel apart een kleur geven.", o: "Scherm: eigenschappen",
    uitleg: "De resolutie zegt hoeveel aanstuurbare kleurstippen (pixels) het scherm heeft (zie Basisbegrippen). \"Aanstuurbaar\" betekent dat de computer elke pixel apart een kleur kan geven. Voorbeelden van de slide: 1024×768 (een oude resolutie bij 4:3) en 1600×1200 (ook 4:3). Hoe hoger de resolutie, hoe scherper en gedetailleerder het beeld." },
  { v: "Welke twee voorbeeldresoluties noemt de cursus bij resolutie?", a: "1024×768 en 1600×1200.", o: "Scherm: eigenschappen", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s15_lcd_scherm.jpg",
    uitleg: "De resolutie zegt hoeveel aanstuurbare kleurstippen (pixels) het scherm heeft (zie Basisbegrippen). \"Aanstuurbaar\" betekent dat de computer elke pixel apart een kleur kan geven. Voorbeelden van de slide: 1024×768 (een oude resolutie bij 4:3) en 1600×1200 (ook 4:3). Hoe hoger de resolutie, hoe scherper en gedetailleerder het beeld." },
  { v: "Wat toont de foto bij de eigenschappen van schermen?", a: "Een plat LCD-scherm.", o: "Scherm: eigenschappen", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s15_lcd_scherm.jpg",
    uitleg: "Wat zie je op de afbeelding? Rechts een foto van een plat LCD-scherm (een zilvergrijs computerscherm op een voet) met een blauw beeld." },

  // ===== Scherm: populaire schermresoluties (slide 16) =====
  { v: "Geef de populaire schermresoluties met hun naam, van groot naar klein.", a: "", o: "Scherm: populaire schermresoluties",
    tabel: [["Naam", "Resolutie"], ["5K", "5120 x 2880"], ["4K", "3840 x 2160 (typical monitor resolution)"], ["4K", "4096 x 2160 (official cinema resolution)"], ["Ultra HD (UHD)", "3840 x 2160"], ["Quad HD (QHD) aka Wide Quad HD (WQHD)", "2560 x 1440"], ["2K", "2560 x 1440 (typical monitor resolution)"], ["2K", "2048 x 1080 (official cinema resolution)"], ["WUXGA", "1920 x 1200"], ["Full HD (FHD) aka 1080p aka HD", "1920 x 1080"], ["HD aka 720p", "1280 x 720"]],
    uitleg: "Bron van de cursus: tomshardware.com.\n\nResolutie = breedte × hoogte in pixels. De namen zijn verwarrend: 4K wordt gebruikt voor 4096 × 2160 (bioscoop) en voor 3840 × 2160 (Ultra HD, tv's en monitors). Full HD heet ook 1080p of HD.\n\nTypical monitor resolution = de gewone resolutie van computerschermen.\nOfficial cinema resolution = de officiële resolutie voor de bioscoop." },
  { v: "Wat is de resolutie van 5K?", a: "5120 x 2880.", o: "Scherm: populaire schermresoluties",
    uitleg: "• 5K: 5120 × 2880." },
  { v: "Geef de 2 resoluties van 4K.", a: "3840 x 2160 (typical monitor resolution) en 4096 x 2160 (official cinema resolution).", o: "Scherm: populaire schermresoluties",
    uitleg: "• 4K: twee varianten: 3840 × 2160 (typical monitor resolution: de gewone 4K bij monitors en tv's) en 4096 × 2160 (official cinema resolution: de officiële 4K voor de bioscoop, iets breder)." },
  { v: "Wat is de resolutie van Ultra HD (UHD)?", a: "3840 x 2160.", o: "Scherm: populaire schermresoluties",
    uitleg: "• Ultra HD (UHD): 3840 × 2160, dus hetzelfde als de gewone 4K." },
  { v: "Wat is de resolutie van Quad HD (QHD), en hoe heet het nog?", a: "2560 x 1440. Het heet ook Wide Quad HD (WQHD).", o: "Scherm: populaire schermresoluties",
    uitleg: "• Quad HD (QHD), ook Wide Quad HD (WQHD) genoemd: 2560 × 1440." },
  { v: "Geef de 2 resoluties van 2K.", a: "2560 x 1440 (typical monitor resolution) en 2048 x 1080 (official cinema resolution).", o: "Scherm: populaire schermresoluties",
    uitleg: "• 2K: twee varianten: 2560 × 1440 (typical monitor resolution) en 2048 × 1080 (official cinema resolution)." },
  { v: "Wat is de resolutie van WUXGA?", a: "1920 x 1200.", o: "Scherm: populaire schermresoluties",
    uitleg: "• WUXGA: 1920 × 1200 (een 16:10-resolutie)." },
  { v: "Wat is de resolutie van Full HD (FHD), en welke 2 andere namen heeft het?", a: "1920 x 1080. Het heet ook 1080p en HD.", o: "Scherm: populaire schermresoluties",
    uitleg: "• Full HD (FHD), ook 1080p of HD genoemd: 1920 × 1080." },
  { v: "Wat is de resolutie van HD aka 720p?", a: "1280 x 720.", o: "Scherm: populaire schermresoluties",
    uitleg: "'aka' = also known as (ook gekend als).\n\n• HD, ook 720p genoemd: 1280 × 720." },
  { v: "Welke naam hoort bij 3840 x 2160?", a: "4K (typical monitor resolution) of Ultra HD (UHD).", o: "Scherm: populaire schermresoluties",
    uitleg: "• 4K: twee varianten: 3840 × 2160 (typical monitor resolution: de gewone 4K bij monitors en tv's) en 4096 × 2160 (official cinema resolution: de officiële 4K voor de bioscoop, iets breder)." },
  { v: "Welke naam hoort bij 2560 x 1440?", a: "Quad HD (QHD), aka Wide Quad HD (WQHD). Ook 2K (typical monitor resolution).", o: "Scherm: populaire schermresoluties",
    uitleg: "• Quad HD (QHD), ook Wide Quad HD (WQHD) genoemd: 2560 × 1440." },
  { v: "Welke naam hoort bij 1920 x 1200?", a: "WUXGA.", o: "Scherm: populaire schermresoluties",
    uitleg: "• WUXGA: 1920 × 1200 (een 16:10-resolutie)." },
  { v: "Zet van groot naar klein: Full HD, 5K, WUXGA, Ultra HD, HD (720p), Quad HD.", a: "5K → Ultra HD → Quad HD → WUXGA → Full HD → HD (720p).", o: "Scherm: populaire schermresoluties",
    uitleg: "Quad HD: \"quad\" betekent vier. 2560 × 1440 heeft vier keer zoveel pixels als HD 720p (twee keer zo breed en twee keer zo hoog)." },
  { v: "Wat betekent de p in 1080p, en waarom heet 4K zo?", a: "p = progressive: elk beeld wordt in één keer volledig getekend. 1080 = het aantal lijnen in de hoogte.\n4K: het beeld is ongeveer 4000 pixels breed.", o: "Scherm: populaire schermresoluties",
    uitleg: "Het tegenovergestelde van progressive is interlaced (1080i): daar wordt om beurten de ene helft van de lijnen getekend en dan de andere helft.\n\nBij 1080p noemt men de hoogte (1080), bij 4K de breedte (3840 of 4096, afgerond 4000)." },
  { v: "Hoeveel keer meer pixels heeft 4K dan 1080p, en hoeveel pixels heeft 720p?", a: "4K heeft 4 keer meer pixels: 2 keer zo breed en 2 keer zo hoog.\n720p (1280 × 720) heeft 921 600 pixels, ongeveer 0,92 MP.", o: "Scherm: populaire schermresoluties",
    uitleg: "- 1080p: 1920 × 1080 = 2 073 600 pixels.\n- 4K (Ultra HD): 3840 × 2160 = 8 294 400 pixels. 3840 = 2 × 1920 en 2160 = 2 × 1080, dus 2 × 2 = 4 keer zoveel.\n\nMP = megapixel = 1 miljoen pixels.\n\n\"p\" (720p, 1080p): het getal is de hoogte in pixels (het aantal rijen). De p staat voor progressive: alle rijen worden in één keer getekend." },
  { v: "Wat zijn de twee varianten van 4K?", a: "3840 × 2160 (monitor) en 4096 × 2160 (officiële cinema).", o: "Scherm: populaire schermresoluties", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s17_resoluties.jpg",
    uitleg: "• 4K: twee varianten: 3840 × 2160 (typical monitor resolution: de gewone 4K bij monitors en tv's) en 4096 × 2160 (official cinema resolution: de officiële 4K voor de bioscoop, iets breder).\n\nEr bestaan veel resoluties, en ze hebben vaak een naam of afkorting. Deze tabel (bron: tomshardware.com) zet de bekendste op een rij, van groot naar klein.\n\nWat zie je op de afbeelding? De tabel heeft twee kolommen: naam en resolutie." },
  { v: "Wat zijn de twee varianten van 2K?", a: "2560 × 1440 (monitor) en 2048 × 1080 (officiële cinema).", o: "Scherm: populaire schermresoluties",
    uitleg: "• 2K: twee varianten: 2560 × 1440 (typical monitor resolution) en 2048 × 1080 (official cinema resolution)." },
  { v: "Wat betekent het getal bij \"p\" (bv. 1080p)?", a: "De hoogte in pixels (aantal rijen).", o: "Scherm: populaire schermresoluties",
    uitleg: "\"p\" (720p, 1080p): het getal is de hoogte in pixels (het aantal rijen). De p staat voor progressive: alle rijen worden in één keer getekend." },
  { v: "Waar staat de p voor in bv. 1080p?", a: "Progressive: alle rijen in één keer getekend.", o: "Scherm: populaire schermresoluties", extra: true,
    uitleg: "\"p\" (720p, 1080p): het getal is de hoogte in pixels (het aantal rijen). De p staat voor progressive: alle rijen worden in één keer getekend." },
  { v: "Wat betekent het getal bij \"K\" (bv. 4K)?", a: "Ongeveer de breedte in duizenden pixels.", o: "Scherm: populaire schermresoluties",
    uitleg: "\"K\" (2K, 4K, 5K): K staat voor kilo, duizend. Het getal is ongeveer de breedte in duizenden pixels: 4K is ongeveer 4000 pixels breed (3840 of 4096)." },
  { v: "Waarom heet Quad HD zo?", a: "Het heeft vier keer zoveel pixels als 720p.", o: "Scherm: populaire schermresoluties", extra: true,
    uitleg: "Quad HD: \"quad\" betekent vier. 2560 × 1440 heeft vier keer zoveel pixels als HD 720p (twee keer zo breed en twee keer zo hoog)." },
  { v: "Hoeveel keer Full HD is 4K?", a: "Vier keer (2× breder en 2× hoger).", o: "Scherm: populaire schermresoluties", extra: true,
    uitleg: "Ook 4K (UHD) is vier keer Full HD: 3840 = 2 × 1920 en 2160 = 2 × 1080." },

  // ===== Scherm: resoluties vergeleken (slide 17) =====
  { v: "Geef van de resoluties 4K tot 720p de resolutie, de beeldverhouding en het aantal pixels.", a: "", o: "Scherm: resoluties vergeleken",
    tabel: [["Naam", "Resolutie", "Verhouding", "Pixels"], ["4K", "3840x2160", "16:9", "8 294 400 (8,29 MP)"], ["1600p", "2560x1600", "16:10", "4 096 000 (4,09 MP)"], ["1440p", "2560x1440", "16:9", "3 686 400 (3,69 MP)"], ["1200p", "1920x1200", "16:10", "2 304 000 (2,3 MP)"], ["1080p", "1920x1080", "16:9", "2 073 600 (2,07 MP)"], ["900p", "1600x900", "16:9", "1 440 000 (1,44 MP)"], ["800p", "1280x800", "16:10", "1 024 000 (1,02 MP)"], ["720p", "1280x720", "16:9", "921 600 (0,92 MP)"]],
    uitleg: "Aantal pixels = breedte × hoogte, bv. 1920 × 1080 = 2 073 600 = ongeveer 2,07 MP. 1 MP (megapixel) = 1 miljoen pixels.\n\nBeeldverhouding: 16:9 is breedbeeld (tv's, de meeste monitors); 16:10 is iets hoger (vaak bij laptops).\n\nDe afbeelding (bron: wccftech.com) toont de resoluties als vakken in elkaar, zodat je ziet hoe groot ze zijn tegenover elkaar." },
  { v: "Welke resolutie hoort bij vak 1 tot 8?", a: "1. 4K (3840x2160) [16:9]\n2. 1600p (2560x1600) [16:10]\n3. 1440p (2560x1440) [16:9]\n4. 1200p (1920x1200) [16:10]\n5. 1080p (1920x1080) [16:9]\n6. 900p (1600x900) [16:9]\n7. 800p (1280x800) [16:10]\n8. 720p (1280x720) [16:9]", o: "Scherm: resoluties vergeleken", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s17_resoluties_vraag.jpg", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s17_resoluties.jpg" },
  { v: "Hoeveel pixels heeft 4K (3840x2160)?", a: "8 294 400 pixels (8,29 MP).", o: "Scherm: resoluties vergeleken",
    uitleg: "• Rood, de grootste: 4K (3840×2160) [16:9]: 8 294 400 pixels (8,29 MP)." },
  { v: "Hoeveel pixels heeft 1080p (1920x1080)?", a: "2 073 600 pixels (2,07 MP).", o: "Scherm: resoluties vergeleken",
    uitleg: "• Lichtgroen: 1080p (1920×1080) [16:9]: 2 073 600 pixels (2,07 MP)." },
  { v: "Welke resoluties in het overzicht hebben de verhouding 16:10?", n: 3, a: "1600p (2560x1600), 1200p (1920x1200) en 800p (1280x800).", o: "Scherm: resoluties vergeleken",
    uitleg: "• Oranje: 1600p (2560×1600) [16:10]: 4 096 000 pixels (4,09 MP).\n\n1600p, 1200p en 800p." },
  { v: "Wat is de resolutie van 900p, 1600p en 800p?", a: "900p = 1600x900\n1600p = 2560x1600\n800p = 1280x800", o: "Scherm: resoluties vergeleken" },
  { v: "Hoe bereken je het aantal pixels van een resolutie?", a: "Breedte × hoogte.", o: "Scherm: resoluties vergeleken",
    uitleg: "Het aantal pixels = breedte × hoogte. Bv. 1920 × 1080 = 2 073 600 pixels ≈ 2,07 MP. MP = megapixel = 1 miljoen pixels.\n\nIn de afbeelding staat bij 800p '1.2MP'. Dat klopt niet: 1 024 000 pixels is 1,02 MP.", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s17_resoluties.jpg" },
  { v: "Hoe toont dit schema de resoluties?", a: "Als gekleurde rechthoeken op schaal, van groot naar klein over elkaar.", o: "Scherm: resoluties vergeleken", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s17_resoluties_vraag.jpg", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s17_resoluties.jpg",
    uitleg: "Dit schema (bron: wccftech.com) toont dezelfde resoluties, maar nu als gekleurde rechthoeken op schaal. Zo zie je in één oogopslag hoeveel groter een resolutie is dan een andere.\n\nWat zie je op de afbeelding? Alle rechthoeken beginnen in de rechteronderhoek en liggen over elkaar, van groot naar klein. Bij elke rechthoek staat links de naam, de resolutie en de beeldverhouding, en rechts het totale aantal pixels:" },
  { v: "Hoeveel pixels heeft 1600p (2560×1600)?", a: "4 096 000 (4,09 MP).", o: "Scherm: resoluties vergeleken",
    uitleg: "• Oranje: 1600p (2560×1600) [16:10]: 4 096 000 pixels (4,09 MP).\n\n• Turquoise, de kleinste: 720p (1280×720) [16:9]: 921 600 pixels (0,92 MP)." },
  { v: "Hoeveel pixels heeft 1440p (2560×1440)?", a: "3 686 400 (3,69 MP).", o: "Scherm: resoluties vergeleken",
    uitleg: "• Geel: 1440p (2560×1440) [16:9]: 3 686 400 pixels (3,69 MP)." },
  { v: "Hoeveel pixels heeft 1200p (1920×1200)?", a: "2 304 000 (2,3 MP).", o: "Scherm: resoluties vergeleken",
    uitleg: "• Donkergroen: 1200p (1920×1200) [16:10]: 2 304 000 pixels (2,3 MP)." },
  { v: "Hoeveel pixels heeft 900p (1600×900)?", a: "1 440 000 (1,44 MP).", o: "Scherm: resoluties vergeleken",
    uitleg: "• Groen: 900p (1600×900) [16:9]: 1 440 000 pixels (1,44 MP)." },
  { v: "Wat is de resolutie en aspect ratio van 800p?", a: "1280×800, 16:10.", o: "Scherm: resoluties vergeleken",
    uitleg: "• Blauwgroen (smalle strook): 800p (1280×800) [16:10]: 1 024 000 pixels (1,02 MP; op de slide staat 1,2 MP)." },
  { v: "Wat is het verschil tussen 1920×1200 en 1920×1080?", a: "Even breed, maar 1920×1200 heeft 120 rijen meer (16:10 i.p.v. 16:9).", o: "Scherm: resoluties vergeleken", extra: true,
    uitleg: "Wat je hieraan ziet: de rode 4K-rechthoek is vier keer zo groot als de lichtgroene 1080p (8,29 MP tegenover 2,07 MP). De 16:10-resoluties zijn even breed als hun 16:9-buur, maar iets hoger: 1920×1200 heeft 120 rijen meer dan 1920×1080. Het aantal pixels bereken je zelf door breedte × hoogte te doen, bv. 1280 × 720 = 921 600." },

  // ===== Projector (slide 18) =====
  { v: "Welke 3 projectortechnologieën bespreekt de cursus?", a: "DLP-beamer, LCD-beamer en LED-beamer.", o: "Projector",
    uitleg: "Een LED-beamer is eigenlijk geen aparte beeldtechniek: hij gebruikt DLP- of LCD-technologie, maar vervangt de traditionele beamerlamp door LED's. Het voordeel: een LED kan tot 20 000 uren werken, terwijl een klassieke lamp maar enkele duizenden uren meegaat en duur is om te vervangen (zie slide 14). Een LED-beamer is ook zuiniger en wordt minder warm." },
  { v: "Hoe maakt een DLP-beamer een afbeelding?", a: "Met een chip gemaakt van kleine microscopische spiegels en een ronddraaiend kleurenwiel.", o: "Projector",
    uitleg: "DLP staat voor Digital Light Processing. De beamer gebruikt een chip met kleine microscopische spiegeltjes: één spiegeltje per pixel, honderdduizenden tot miljoenen op één chip. Elk spiegeltje kan heel snel kantelen: naar de lens (de pixel is licht) of ervan weg (de pixel is donker). Voor de kleur draait er een kleurenwiel (een schijf met rode, groene en blauwe filters) razendsnel voor de lamp. De kleuren worden zo snel na elkaar getoond dat je ogen ze mengen tot één kleurenbeeld." },
  { v: "Welke technologie gebruikt een LCD-beamer?", a: "Dezelfde liquid crystal display-technologie die in elektronische horloges te vinden is.", o: "Projector", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s18_projector.jpg",
    uitleg: "Een LCD-beamer gebruikt dezelfde liquid crystal display-technologie die je in elektronische horloges (en in LCD-schermen) vindt. Het licht van de lamp gaat door kleine LCD-paneeltjes (meestal drie: voor rood, groen en blauw), die per pixel meer of minder licht doorlaten. Daarna worden de drie kleuren samengevoegd en door de lens geprojecteerd." },
  { v: "Welke beamer gebruikt een ronddraaiend kleurenwiel?", a: "De DLP-beamer.", o: "Projector",
    uitleg: "Een beamer is een projector: hij werpt het beeld groot op een muur of doek.\n\nDLP staat voor Digital Light Processing. De beamer gebruikt een chip met kleine microscopische spiegeltjes: één spiegeltje per pixel, honderdduizenden tot miljoenen op één chip. Elk spiegeltje kan heel snel kantelen: naar de lens (de pixel is licht) of ervan weg (de pixel is donker). Voor de kleur draait er een kleurenwiel (een schijf met rode, groene en blauwe filters) razendsnel voor de lamp. De kleuren worden zo snel na elkaar getoond dat je ogen ze mengen tot één kleurenbeeld." },
  { v: "Wat is het verschil tussen een LED-beamer en een DLP- of LCD-beamer?", a: "Een LED-beamer gebruikt DLP- of LCD-technologie, maar vervangt de traditionele beamerlampen.", o: "Projector",
    uitleg: "Een LED-beamer is eigenlijk geen aparte beeldtechniek: hij gebruikt DLP- of LCD-technologie, maar vervangt de traditionele beamerlamp door LED's. Het voordeel: een LED kan tot 20 000 uren werken, terwijl een klassieke lamp maar enkele duizenden uren meegaat en duur is om te vervangen (zie slide 14). Een LED-beamer is ook zuiniger en wordt minder warm." },
  { v: "Hoe lang kan een LED-beamer werken?", a: "Tot 20 000 uren.", o: "Projector",
    uitleg: "Een LED-beamer is eigenlijk geen aparte beeldtechniek: hij gebruikt DLP- of LCD-technologie, maar vervangt de traditionele beamerlamp door LED's. Het voordeel: een LED kan tot 20 000 uren werken, terwijl een klassieke lamp maar enkele duizenden uren meegaat en duur is om te vervangen (zie slide 14). Een LED-beamer is ook zuiniger en wordt minder warm." },
  { v: "Welk toestel zie je op deze foto?", a: "Een projector (beamer).", o: "Projector", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s18_projector.jpg",
    uitleg: "Een projector (in België vaak beamer genoemd) werpt het beeld van de computer vergroot op een muur of doek, bv. in een klaslokaal of vergaderzaal. Er bestaan drie technologieën:" },
  { v: "DLP voluit", a: "DLP = Digital Light Processing. Elk spiegeltje op de chip is één pixel en kantelt duizenden keren per seconde.", o: "Projector", extra: true,
    uitleg: "DLP staat voor Digital Light Processing. De beamer gebruikt een chip met kleine microscopische spiegeltjes: één spiegeltje per pixel, honderdduizenden tot miljoenen op één chip. Elk spiegeltje kan heel snel kantelen: naar de lens (de pixel is licht) of ervan weg (de pixel is donker). Voor de kleur draait er een kleurenwiel (een schijf met rode, groene en blauwe filters) razendsnel voor de lamp. De kleuren worden zo snel na elkaar getoond dat je ogen ze mengen tot één kleurenbeeld." },
  { v: "Waarvoor staat DLP, en wat stelt één spiegeltje van een DLP-chip voor?", a: "Digital Light Processing. Eén spiegeltje stelt één pixel voor.", o: "Projector",
    uitleg: "Een DLP-chip heeft heel veel microscopisch kleine spiegeltjes. Elk spiegeltje kantelt duizenden keren per seconde: naar de lens toe (pixel licht) of weg ervan (pixel donker). Zo ontstaat het beeld.\n\nBij een DLP-beamer kantelen duizenden piepkleine spiegeltjes het licht naar het doek of ervan weg; het draaiende kleurenwiel geeft er kleur aan." },
  { v: "Wat is een LED-beamer, en waarom is hij voordelig?", a: "Een beamer met DLP- of LCD-technologie, waarbij de gewone lamp vervangen is door leds.\nDe leds gaan veel langer mee (tot 20 000 uur), dus je hoeft geen dure lamp te vervangen.", o: "Projector",
    uitleg: "Bij een gewone beamer slijt de lamp na een paar duizend uur, en een nieuwe lamp is duur. Leds gaan veel langer mee en worden minder warm.\n\nEen LED-beamer is geen aparte techniek voor het beeld: hij werkt met DLP of LCD, maar het licht komt van LED's in plaats van een klassieke lamp. Die gaan veel langer mee, dus je moet geen dure lamp vervangen (zie slide 14)." },
  { v: "Wat doet een projector?", a: "Het beeld vergroot op een muur of doek werpen.", o: "Projector", extra: true,
    uitleg: "Een projector (in België vaak beamer genoemd) werpt het beeld van de computer vergroot op een muur of doek, bv. in een klaslokaal of vergaderzaal. Er bestaan drie technologieën:" },
  { v: "Hoe noemt men een projector in België vaak?", a: "Een beamer.", o: "Projector",
    uitleg: "Een projector (in België vaak beamer genoemd) werpt het beeld van de computer vergroot op een muur of doek, bv. in een klaslokaal of vergaderzaal. Er bestaan drie technologieën:" },
  { v: "Welke drie projectortechnologieën bestaan er?", a: "DLP, LCD en LED.", o: "Projector",
    uitleg: "Een LED-beamer is eigenlijk geen aparte beeldtechniek: hij gebruikt DLP- of LCD-technologie, maar vervangt de traditionele beamerlamp door LED's. Het voordeel: een LED kan tot 20 000 uren werken, terwijl een klassieke lamp maar enkele duizenden uren meegaat en duur is om te vervangen (zie slide 14). Een LED-beamer is ook zuiniger en wordt minder warm." },
  { v: "Wat doet elk spiegeltje in een DLP-beamer?", a: "Het kantelt naar de lens (licht) of ervan weg (donker); één per pixel.", o: "Projector", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s18_projector.jpg",
    uitleg: "DLP staat voor Digital Light Processing. De beamer gebruikt een chip met kleine microscopische spiegeltjes: één spiegeltje per pixel, honderdduizenden tot miljoenen op één chip. Elk spiegeltje kan heel snel kantelen: naar de lens (de pixel is licht) of ervan weg (de pixel is donker). Voor de kleur draait er een kleurenwiel (een schijf met rode, groene en blauwe filters) razendsnel voor de lamp. De kleuren worden zo snel na elkaar getoond dat je ogen ze mengen tot één kleurenbeeld.\n\nWat zie je op de afbeelding? Onderaan een foto van een kleine witte beamer met een ronde lens vooraan, die blauwig oplicht. Bovenop zitten bedieningsknoppen." },
  { v: "Wat doet het kleurenwiel in een DLP-beamer?", a: "Het toont razendsnel rood, groen en blauw na elkaar; je ogen mengen ze tot één kleurenbeeld.", o: "Projector", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s18_projector.jpg",
    uitleg: "DLP staat voor Digital Light Processing. De beamer gebruikt een chip met kleine microscopische spiegeltjes: één spiegeltje per pixel, honderdduizenden tot miljoenen op één chip. Elk spiegeltje kan heel snel kantelen: naar de lens (de pixel is licht) of ervan weg (de pixel is donker). Voor de kleur draait er een kleurenwiel (een schijf met rode, groene en blauwe filters) razendsnel voor de lamp. De kleuren worden zo snel na elkaar getoond dat je ogen ze mengen tot één kleurenbeeld." },
  { v: "Hoe werkt een LCD-beamer kort?", a: "Licht gaat door (meestal drie) LCD-paneeltjes voor rood, groen en blauw, die worden samengevoegd.", o: "Projector", extra: true,
    uitleg: "Een LCD-beamer gebruikt dezelfde liquid crystal display-technologie die je in elektronische horloges (en in LCD-schermen) vindt. Het licht van de lamp gaat door kleine LCD-paneeltjes (meestal drie: voor rood, groen en blauw), die per pixel meer of minder licht doorlaten. Daarna worden de drie kleuren samengevoegd en door de lens geprojecteerd." },
  { v: "Welke technologie gebruikt een LED-beamer?", a: "DLP of LCD, maar met LED's in plaats van de traditionele lamp.", o: "Projector",
    uitleg: "Een LED-beamer is eigenlijk geen aparte beeldtechniek: hij gebruikt DLP- of LCD-technologie, maar vervangt de traditionele beamerlamp door LED's. Het voordeel: een LED kan tot 20 000 uren werken, terwijl een klassieke lamp maar enkele duizenden uren meegaat en duur is om te vervangen (zie slide 14). Een LED-beamer is ook zuiniger en wordt minder warm." },
  { v: "Noem nog twee voordelen van een LED-beamer.", a: "Zuiniger en wordt minder warm.", o: "Projector", extra: true,
    uitleg: "Een LED-beamer is eigenlijk geen aparte beeldtechniek: hij gebruikt DLP- of LCD-technologie, maar vervangt de traditionele beamerlamp door LED's. Het voordeel: een LED kan tot 20 000 uren werken, terwijl een klassieke lamp maar enkele duizenden uren meegaat en duur is om te vervangen (zie slide 14). Een LED-beamer is ook zuiniger en wordt minder warm." },

  // ===== Geluid (slide 19) =====
  { v: "Wat doet de DAC op een geluidskaart?", a: "Omzetten van digitaal naar analoog.", o: "Geluid",
    uitleg: "De computer werkt digitaal (enen en nullen), maar een luidspreker heeft een analoog signaal nodig (een spanning die vloeiend op en neer gaat). De DAC (Digital-to-Analog Converter) doet die omzetting.\n\nDe computer bewaart geluid digitaal (als enen en nullen, bv. een mp3-bestand). Een luidspreker of hoofdtelefoon werkt analoog: het membraan moet trillen op een vloeiend veranderende spanning. De geluidskaart zet het digitale geluid daarom om naar analoog met een DAC (Digital-to-Analog Converter)." },
  { v: "Welke omzetting gebruikt de microfooningang van een geluidskaart?", a: "Een ADC (analoog naar digitaal).", o: "Geluid",
    uitleg: "Microfoon (ADC): een microfoon vangt geluid op als een analoog signaal. De geluidskaart zet het om naar digitaal met een ADC (Analog-to-Digital Converter), zodat de computer het kan opslaan of doorsturen (bv. bij een videogesprek)." },
  { v: "Wat is het verschil tussen een DAC en een ADC?", a: "DAC: digitaal → analoog (voor de luidsprekers).\nADC: analoog → digitaal (voor de microfoon).", o: "Geluid",
    uitleg: "Microfoon (ADC): een microfoon vangt geluid op als een analoog signaal. De geluidskaart zet het om naar digitaal met een ADC (Analog-to-Digital Converter), zodat de computer het kan opslaan of doorsturen (bv. bij een videogesprek)." },
  { v: "Geef de 3 extra in-uitgangen van een geluidskaart uit de cursus.", a: "Microfoon (ADC), hoofdtelefoon en Midi.", o: "Geluid",
    uitleg: "Microfoon (ADC): een microfoon vangt geluid op als een analoog signaal. De geluidskaart zet het om naar digitaal met een ADC (Analog-to-Digital Converter), zodat de computer het kan opslaan of doorsturen (bv. bij een videogesprek)." },
  { v: "Geef 3 surroundsystemen uit de cursus.", a: "5.1, 6.1 en 7.1.", o: "Geluid",
    uitleg: "6.1: 6 luidsprekers (de 5 van 5.1 plus een midden-achter) + 1 subwoofer." },
  { v: "Wat betekent 5.1 bij surround?", a: "5 luidsprekers en 1 subwoofer (lage tonen).", o: "Geluid",
    uitleg: "Bij surround staan er luidsprekers rondom je, zodat het geluid van alle kanten komt, zoals in de bioscoop. De naam bestaat uit twee getallen: het eerste is het aantal gewone luidsprekers, het tweede (\".1\") is de subwoofer: een luidspreker speciaal voor de lage tonen (bas)." },
  { v: "Wat is MIDI, en wat doet de subwoofer (de .1 in 5.1)?", a: "MIDI: een standaard om muziekinstrumenten (bv. een keyboard) aan te sluiten.\nDe subwoofer speelt de lage tonen.", o: "Geluid",
    uitleg: "MIDI stuurt geen geluid, maar noten: welke toets, hoe hard, hoe lang. De computer of het instrument maakt er dan geluid van.\n\nBij surroundsystemen zoals 5.1 staat de 5 voor 5 gewone luidsprekers (vooraan links, midden, rechts, achteraan links en rechts) en de .1 voor de subwoofer.\n\nMIDI is een aansluiting voor elektronische muziekinstrumenten, zoals een keyboard." },
  { v: "Welk onderdeel zorgt voor geluid in de computer?", a: "De geluidskaart.", o: "Geluid",
    uitleg: "Om geluid te maken en op te nemen heeft de computer een geluidskaart. Vroeger was dat een aparte insteekkaart, vandaag zit ze bijna altijd ingebouwd op het moederbord (onboard).\n\nHoofdtelefoon: een uitgang voor je koptelefoon of oortjes." },
  { v: "Waar zit de geluidskaart vandaag meestal?", a: "Ingebouwd op het moederbord (onboard).", o: "Geluid", extra: true,
    uitleg: "Om geluid te maken en op te nemen heeft de computer een geluidskaart. Vroeger was dat een aparte insteekkaart, vandaag zit ze bijna altijd ingebouwd op het moederbord (onboard)." },
  { v: "Welke omzetting doet de geluidskaart voor luidsprekers?", a: "Digitaal naar analoog, met een DAC.", o: "Geluid",
    uitleg: "De computer bewaart geluid digitaal (als enen en nullen, bv. een mp3-bestand). Een luidspreker of hoofdtelefoon werkt analoog: het membraan moet trillen op een vloeiend veranderende spanning. De geluidskaart zet het digitale geluid daarom om naar analoog met een DAC (Digital-to-Analog Converter).\n\nGoed om te weten: De gekleurde geluidspoorten achteraan de pc (groen voor luidsprekers, roze voor de microfoon, blauw voor de lijn-ingang, en zwart, oranje en grijs voor extra surround-luidsprekers) zijn de aansluitingen van de geluidskaart (zie hoofdstuk 7, slide 27)." },
  { v: "Waarom moet de geluidskaart digitaal omzetten naar analoog voor de luidsprekers?", a: "Luidsprekers werken analoog: het membraan trilt op een vloeiend veranderende spanning.", o: "Geluid", extra: true,
    uitleg: "De computer bewaart geluid digitaal (als enen en nullen, bv. een mp3-bestand). Een luidspreker of hoofdtelefoon werkt analoog: het membraan moet trillen op een vloeiend veranderende spanning. De geluidskaart zet het digitale geluid daarom om naar analoog met een DAC (Digital-to-Analog Converter)." },
  { v: "Welke omzetting is nodig bij een microfoon?", a: "Analoog naar digitaal, met een ADC.", o: "Geluid",
    uitleg: "Microfoon (ADC): een microfoon vangt geluid op als een analoog signaal. De geluidskaart zet het om naar digitaal met een ADC (Analog-to-Digital Converter), zodat de computer het kan opslaan of doorsturen (bv. bij een videogesprek)." },
  { v: "Waar staat MIDI voor?", a: "Musical Instrument Digital Interface.", o: "Geluid", extra: true,
    uitleg: "MIDI: Musical Instrument Digital Interface, een aansluiting voor elektronische muziekinstrumenten zoals een keyboard (synthesizer). MIDI stuurt geen geluid door, maar muzieknoten als opdrachten (\"speel deze noot, zo hard, zo lang\")." },
  { v: "Waarvoor dient MIDI?", a: "Om elektronische muziekinstrumenten (bv. keyboard) aan te sluiten.", o: "Geluid",
    uitleg: "MIDI: Musical Instrument Digital Interface, een aansluiting voor elektronische muziekinstrumenten zoals een keyboard (synthesizer). MIDI stuurt geen geluid door, maar muzieknoten als opdrachten (\"speel deze noot, zo hard, zo lang\")." },
  { v: "Wat stuurt MIDI door?", a: "Geen geluid, maar muzieknoten als opdrachten.", o: "Geluid", extra: true,
    uitleg: "MIDI: Musical Instrument Digital Interface, een aansluiting voor elektronische muziekinstrumenten zoals een keyboard (synthesizer). MIDI stuurt geen geluid door, maar muzieknoten als opdrachten (\"speel deze noot, zo hard, zo lang\")." },
  { v: "Wat is surround?", a: "Luidsprekers rondom je, zodat geluid van alle kanten komt.", o: "Geluid",
    uitleg: "Bij surround staan er luidsprekers rondom je, zodat het geluid van alle kanten komt, zoals in de bioscoop. De naam bestaat uit twee getallen: het eerste is het aantal gewone luidsprekers, het tweede (\".1\") is de subwoofer: een luidspreker speciaal voor de lage tonen (bas)." },
  { v: "Wat betekent het eerste getal bij surround (bv. de 5 in 5.1)?", a: "Het aantal gewone luidsprekers.", o: "Geluid", extra: true,
    uitleg: "Bij surround staan er luidsprekers rondom je, zodat het geluid van alle kanten komt, zoals in de bioscoop. De naam bestaat uit twee getallen: het eerste is het aantal gewone luidsprekers, het tweede (\".1\") is de subwoofer: een luidspreker speciaal voor de lage tonen (bas).\n\nDe \"…\" betekent dat er nog grotere systemen bestaan, bv. 9.1." },
  { v: "Wat betekent de .1 bij surround (bv. 5.1)?", a: "De subwoofer, voor de lage tonen (bas).", o: "Geluid",
    uitleg: "Bij surround staan er luidsprekers rondom je, zodat het geluid van alle kanten komt, zoals in de bioscoop. De naam bestaat uit twee getallen: het eerste is het aantal gewone luidsprekers, het tweede (\".1\") is de subwoofer: een luidspreker speciaal voor de lage tonen (bas)." },
  { v: "Wat is 5.1?", a: "5 luidsprekers (links-, midden-, rechts-voor, links- en rechts-achter) + 1 subwoofer.", o: "Geluid",
    uitleg: "5.1: 5 luidsprekers (links-voor, midden-voor, rechts-voor, links-achter, rechts-achter) + 1 subwoofer." },
  { v: "Wat is 6.1?", a: "De 5 van 5.1 plus een midden-achter + 1 subwoofer.", o: "Geluid",
    uitleg: "6.1: 6 luidsprekers (de 5 van 5.1 plus een midden-achter) + 1 subwoofer." },
  { v: "Wat is 7.1?", a: "De 5 van 5.1 plus twee aan de zijkanten + 1 subwoofer.", o: "Geluid",
    uitleg: "7.1: 7 luidsprekers (de 5 van 5.1 plus twee aan de zijkanten) + 1 subwoofer." },

  // ===== Netwerken en modems (extra: staat in de inhoud, maar geen slide) =====
  { v: "Wat doet een netwerkkaart?", a: "Ze verbindt de computer met een netwerk, via kabel of wifi.", o: "Netwerken en modems", extra: true,
    uitleg: "Een netwerkkaart (NIC, Network Interface Card) verbindt de computer met een netwerk: met een kabel (de vierkante LAN-poort, bv. Gigabit Ethernet: 1 Gbit/s) of draadloos via wifi. Vandaag zit ze meestal ingebouwd op het moederbord." },
  { v: "Waar staat NIC voor?", a: "Network Interface Card.", o: "Netwerken en modems", extra: true,
    uitleg: "Een netwerkkaart (NIC, Network Interface Card) verbindt de computer met een netwerk: met een kabel (de vierkante LAN-poort, bv. Gigabit Ethernet: 1 Gbit/s) of draadloos via wifi. Vandaag zit ze meestal ingebouwd op het moederbord." },
  { v: "Waar staat modem voor?", a: "Modulator-demodulator.", o: "Netwerken en modems", extra: true,
    uitleg: "Een modem (modulator-demodulator) zet de digitale signalen van de computer om in signalen die over een andere lijn kunnen reizen, bv. de telefoonlijn of de tv-kabel, en terug. Zo kom je op het internet. Vroeger zat er een inbelmodem in de pc; nu gebruik je een modem van je internetprovider." },
  { v: "Wat doet een modem?", a: "Digitale signalen omzetten om over een andere lijn (telefoon, tv-kabel) te reizen, en terug.", o: "Netwerken en modems", extra: true,
    uitleg: "Een modem (modulator-demodulator) zet de digitale signalen van de computer om in signalen die over een andere lijn kunnen reizen, bv. de telefoonlijn of de tv-kabel, en terug. Zo kom je op het internet. Vroeger zat er een inbelmodem in de pc; nu gebruik je een modem van je internetprovider.\n\nDit onderwerp staat in de inhoudstafel, maar er zit geen slide over in deze PDF. Daarom hier kort de basis, zodat je de begrippen kent." },
  { v: "Tot welke USB-apparaatklasse hoort een modem?", a: "Communications device.", o: "Netwerken en modems", extra: true,
    uitleg: "Goed om te weten: Een netwerkkaart en een modem zijn allebei invoer- én uitvoerapparaten: ze versturen én ontvangen gegevens. Een modem op USB hoort bij de apparaatklasse \"communications device\" (hoofdstuk 7)." },

  // ===== Scanner (slide 20) =====
  { v: "Welke onderdelen van de scanner staan op plaats 1 tot 6?", a: "1. document to be scanned (het document)\n2. glass plate (glasplaat)\n3. movable light source (beweegbare lichtbron)\n4. fixed mirror (vaste spiegel)\n5. movable mirror (beweegbare spiegel)\n6. CCD capture device (sensor)", o: "Scanner", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s20_scanner_vraag.jpg", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s20_scanner.jpg",
    uitleg: "Zo werkt een flatbedscanner (een scanner met een glasplaat, zoals op een kopieertoestel):\n1. Je legt het document op de glasplaat (glass plate).\n2. Een beweegbare lichtbron (movable light source) schuift onder het glas en verlicht het document lijn per lijn.\n3. Het weerkaatste licht gaat via de beweegbare spiegel (movable mirror) naar de vaste spiegel (fixed mirror).\n4. De vaste spiegel stuurt het licht naar de CCD-sensor (CCD capture device). Die meet rood, groen en blauw licht en maakt er een digitaal beeld van." },
  { v: "Welke onderdelen van een scanner bewegen, volgens het schema?", n: 2, a: "De movable light source (lichtbron) en de movable mirror (beweegbare spiegel).", o: "Scanner", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s20_scanner_vraag.jpg", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s20_scanner.jpg",
    uitleg: "• Daaronder zit een movable light source (beweegbare lichtbron), met een dubbele pijl: hij schuift van links naar rechts onder het glas door en verlicht telkens één smalle strook van het document." },
  { v: "Welke spiegel in de scanner beweegt niet?", a: "De fixed mirror.", o: "Scanner",
    uitleg: "• Het licht weerkaatst op het document en gaat via een movable mirror (beweegbare spiegel, rechts, ook met een dubbele pijl) naar een fixed mirror (vaste spiegel, links). De stippellijnen tonen de weg van het licht." },
  { v: "Welk onderdeel vangt het licht op in de scanner?", a: "Het CCD capture device.", o: "Scanner",
    uitleg: "• De vaste spiegel stuurt het licht naar beneden naar het CCD capture device: de lichtsensor, met drie gekleurde blokjes rood, groen en blauw." },
  { v: "Welke 3 kleuren toont het CCD capture device in het schema?", a: "Rood, groen en blauw.", o: "Scanner", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s20_scanner_vraag.jpg", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s20_scanner.jpg",
    uitleg: "• De vaste spiegel stuurt het licht naar beneden naar het CCD capture device: de lichtsensor, met drie gekleurde blokjes rood, groen en blauw." },
  { v: "Beschrijf de weg van het licht in de scanner.", a: "Movable light source → document op de glass plate → movable mirror → fixed mirror → CCD capture device.", o: "Scanner", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s20_scanner.jpg",
    uitleg: "• Het licht weerkaatst op het document en gaat via een movable mirror (beweegbare spiegel, rechts, ook met een dubbele pijl) naar een fixed mirror (vaste spiegel, links). De stippellijnen tonen de weg van het licht." },
  { v: "CCD voluit", a: "CCD = Charge-Coupled Device: een lichtgevoelige sensor, zoals in oudere fotocamera's.", o: "Scanner", extra: true },
  { v: "Waarvoor staat CCD, en hoe verlicht de scanner het document?", a: "Charge-Coupled Device: een lichtgevoelige sensor.\nLijn per lijn, met een lichtbron die onder de glasplaat beweegt.", o: "Scanner",
    uitleg: "Een lamp en de sensor bewegen samen onder de glasplaat. Het licht weerkaatst op het document, en de CCD-sensor meet voor elke lijn hoeveel licht (en welke kleur) terugkomt. Lijn na lijn ontstaat zo een digitale afbeelding." },
  { v: "Wat doet een scanner?", a: "Een digitale afbeelding maken van een papieren document of foto.", o: "Scanner", extra: true,
    uitleg: "Een scanner maakt een digitale afbeelding van een papieren document of foto, zodat je het op de computer kan bekijken, bewaren of doorsturen. Het is dus een invoerapparaat. Deze slide heeft geen tekst, enkel een schema van hoe een flatbedscanner (de platte scanner waarbij je het document op een glasplaat legt) vanbinnen werkt." },
  { v: "Is een scanner een invoer- of uitvoerapparaat?", a: "Een invoerapparaat.", o: "Scanner", extra: true,
    uitleg: "Een scanner maakt een digitale afbeelding van een papieren document of foto, zodat je het op de computer kan bekijken, bewaren of doorsturen. Het is dus een invoerapparaat. Deze slide heeft geen tekst, enkel een schema van hoe een flatbedscanner (de platte scanner waarbij je het document op een glasplaat legt) vanbinnen werkt." },
  { v: "Welk type scanner toont dit schema?", a: "Een flatbedscanner.", o: "Scanner", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s20_scanner_vraag.jpg", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s20_scanner.jpg",
    uitleg: "Wat zie je op de afbeelding? Het schema toont een zijaanzicht van de scanner:" },
  { v: "Waar ligt het document in een flatbedscanner?", a: "Op de glass plate (glasplaat), met de bedrukte kant naar beneden.", o: "Scanner", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s20_scanner.jpg",
    uitleg: "• Bovenaan ligt het document to be scanned (het te scannen document) op de glass plate (glasplaat).\n\n1. Je legt het document met de bedrukte kant naar beneden op de glasplaat." },
  { v: "Wat doet de movable light source in een flatbedscanner?", a: "Ze schuift onder het glas door en verlicht telkens een smalle strook.", o: "Scanner", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s20_scanner.jpg",
    uitleg: "• Daaronder zit een movable light source (beweegbare lichtbron), met een dubbele pijl: hij schuift van links naar rechts onder het glas door en verlicht telkens één smalle strook van het document.\n\n2. De lichtbron schuift lijn per lijn onder het document door." },
  { v: "Welke twee spiegels zitten er in een flatbedscanner?", a: "Een movable mirror (beweegbaar) en een fixed mirror (vast).", o: "Scanner", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s20_scanner.jpg",
    uitleg: "• Het licht weerkaatst op het document en gaat via een movable mirror (beweegbare spiegel, rechts, ook met een dubbele pijl) naar een fixed mirror (vaste spiegel, links). De stippellijnen tonen de weg van het licht." },
  { v: "Waar gaat het licht in een flatbedscanner uiteindelijk naartoe?", a: "Naar het CCD capture device (de lichtsensor).", o: "Scanner", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s20_scanner.jpg",
    uitleg: "• De vaste spiegel stuurt het licht naar beneden naar het CCD capture device: de lichtsensor, met drie gekleurde blokjes rood, groen en blauw.\n\n4. Via de spiegels komt dat weerkaatste licht bij de CCD-sensor. Die meet per punt hoeveel rood, groen en blauw licht er binnenkomt en zet dat om in een elektrisch signaal." },
  { v: "Wat weerkaatsen witte en donkere delen van een document in de scanner?", a: "Witte delen veel licht, donkere delen weinig.", o: "Scanner", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s20_scanner.jpg",
    uitleg: "3. Witte delen van het document weerkaatsen veel licht, donkere delen weinig, gekleurde delen vooral hun eigen kleur." },
  { v: "Hoe bouwt de scanner de afbeelding op?", a: "Lijn na lijn, uit pixels met een RGB-kleur.", o: "Scanner", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s20_scanner.jpg",
    uitleg: "5. Zo bouwt de scanner lijn na lijn een digitale afbeelding op, uit pixels met een RGB-kleur." },
  { v: "Waarom zitten er spiegels in een flatbedscanner?", a: "Zodat het licht altijd een even lange weg aflegt en het beeld overal scherp blijft.", o: "Scanner", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s20_scanner.jpg", extra: true,
    uitleg: "De spiegels zorgen dat het licht altijd een even lange weg aflegt naar de sensor, hoe ver de lichtbron ook geschoven is. Zo blijft het beeld overal scherp." },

  // ===== Printer: matrix, thermisch en inkjet (slide 21) =====
  { v: "Hoe drukt een matrixprinter af?", a: "Met een printkop met pennetjes.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "De printkop van een matrixprinter heeft kleine pennetjes die door een inktlint op het papier slaan, zoals een typemachine. Elk teken is een patroon van puntjes.\n\nEen matrixprinter (naaldprinter) heeft een printkop met pennetjes (naaldjes). De printkop beweegt over het papier, en de pennetjes slaan door een inktlint (zoals bij een typemachine) tegen het papier. Elke letter wordt opgebouwd uit puntjes in een raster (een matrix). Hij is luid en traag, maar wordt nog steeds gebruikt:" },
  { v: "Waarvoor wordt een matrixprinter nog steeds gebruikt?", n: 4, a: "Rekeningen, stoffige omgevingen, kettingpapier en doordrukken.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Een matrixprinter (naaldprinter) heeft een printkop met pennetjes (naaldjes). De printkop beweegt over het papier, en de pennetjes slaan door een inktlint (zoals bij een typemachine) tegen het papier. Elke letter wordt opgebouwd uit puntjes in een raster (een matrix). Hij is luid en traag, maar wordt nog steeds gebruikt:" },
  { v: "Welke printer kan doordrukken?", a: "De matrixprinter.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Een printer zet digitale documenten op papier: een uitvoerapparaat. Er bestaan verschillende soorten, elk met hun eigen techniek en gebruik." },
  { v: "Wat heeft een thermische printer nodig, en waarvoor wordt hij gebruikt?", a: "Speciaal papier. Hij wordt gebruikt voor kastickets.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Een inkjetprinter spuit kleine druppeltjes inkt door kleine spuitmondjes op het papier. De printer zelf is goedkoop, maar de inktpatronen zijn duur.\n\nEen thermische printer werkt met warmte en heeft speciaal papier nodig: thermisch papier dat zwart wordt waar het verwarmd wordt. Er is dus geen inkt nodig. Je vindt ze vooral voor kastickets in winkels. Nadeel: de print vervaagt na een tijd en in de zon." },
  { v: "Hoe drukt een inkjetprinter af?", a: "Met kleine spuitmondjes.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Een inkjetprinter spuit met kleine spuitmondjes (nozzles) heel kleine druppeltjes vloeibare inkt op het papier. De meest voorkomende printer voor thuis." },
  { v: "Wat is het voordeel en het nadeel van een inkjetprinter?", a: "Goedkoop in aankoop, maar duur in inkt.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Goedkoop in aankoop, duur in inkt: de printer zelf kost weinig, maar de inktpatronen zijn duur. Fabrikanten verdienen vooral aan de inkt." },
  { v: "Waarvoor is een inkjetprinter goed?", a: "Voor kleine hoeveelheden, bijvoorbeeld thuisgebruik.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Goed voor kleine hoeveelheden, bijvoorbeeld thuisgebruik. Ook goed voor kleurenfoto's. Gebruik je hem lang niet, dan kan de inkt in de spuitmondjes indrogen." },
  { v: "Welk printertype kies je voor: 1. kastickets, 2. een rekening met doorslag, 3. af en toe thuis printen?", a: "1. Thermische printer\n2. Matrixprinter\n3. Inkjetprinter", o: "Printer: matrix, thermisch en inkjet" },
  { v: "Geef de 3 printertypes van slide 21.", a: "Matrixprinter, thermische printer en inkjetprinter.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Een thermische printer werkt met warmte en heeft speciaal papier nodig: thermisch papier dat zwart wordt waar het verwarmd wordt. Er is dus geen inkt nodig. Je vindt ze vooral voor kastickets in winkels. Nadeel: de print vervaagt na een tijd en in de zon." },
  { v: "Wat is kettingpapier, en hoe werkt een thermische printer?", a: "Kettingpapier: één lange strook papier met gaatjes aan de zijkant.\nThermische printer: met warmte op warmtegevoelig papier, zonder inkt.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Kettingpapier gebruikte men bij matrixprinters: de gaatjes zorgen ervoor dat de printer het papier gelijkmatig kan doortrekken.\n\nThermische printers vind je bv. bij kassatickets: het papier wordt donker waar het verwarmd wordt.\n\nKettingpapier is één lange strook papier met gaatjes aan de zijkanten, die aan elkaar hangt.\nDoordrukken: omdat de pennetjes hard slaan, komt de afdruk ook op de vellen eronder (doorslagpapier). Zo maak je in één keer een kopie, bv. van een rekening.\n\nEen thermische printer werkt met warmte. Het speciale papier wordt zwart waar het warm wordt; er is geen inkt nodig. Daarom vervagen kastickets na een tijd." },
  { v: "Is een printer een invoer- of uitvoerapparaat?", a: "Een uitvoerapparaat.", o: "Printer: matrix, thermisch en inkjet", extra: true,
    uitleg: "Een printer zet digitale documenten op papier: een uitvoerapparaat. Er bestaan verschillende soorten, elk met hun eigen techniek en gebruik." },
  { v: "Welke drie printers behandelt de cursus naast de laserprinter?", a: "Matrixprinter, thermische printer en inkjetprinter.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Een thermische printer werkt met warmte en heeft speciaal papier nodig: thermisch papier dat zwart wordt waar het verwarmd wordt. Er is dus geen inkt nodig. Je vindt ze vooral voor kastickets in winkels. Nadeel: de print vervaagt na een tijd en in de zon." },
  { v: "Hoe werkt een matrixprinter?", a: "Een printkop met pennetjes slaat door een inktlint tegen het papier; letters bestaan uit puntjes.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Een matrixprinter (naaldprinter) heeft een printkop met pennetjes (naaldjes). De printkop beweegt over het papier, en de pennetjes slaan door een inktlint (zoals bij een typemachine) tegen het papier. Elke letter wordt opgebouwd uit puntjes in een raster (een matrix). Hij is luid en traag, maar wordt nog steeds gebruikt:" },
  { v: "Wordt de matrixprinter nog gebruikt?", a: "Ja, nog steeds.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Een matrixprinter (naaldprinter) heeft een printkop met pennetjes (naaldjes). De printkop beweegt over het papier, en de pennetjes slaan door een inktlint (zoals bij een typemachine) tegen het papier. Elke letter wordt opgebouwd uit puntjes in een raster (een matrix). Hij is luid en traag, maar wordt nog steeds gebruikt:" },
  { v: "Noem de vier toepassingen van de matrixprinter.", a: "Rekeningen, stoffige omgevingen, kettingpapier en doordrukken.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Stoffige omgevingen: het is een eenvoudige, robuuste techniek die tegen stof kan (bv. in fabrieken).\n\nRekeningen: voor facturen en documenten in winkels, garages en magazijnen." },
  { v: "Waarom werkt een matrixprinter goed in stoffige omgevingen?", a: "Het is een eenvoudige, robuuste techniek.", o: "Printer: matrix, thermisch en inkjet", extra: true,
    uitleg: "Stoffige omgevingen: het is een eenvoudige, robuuste techniek die tegen stof kan (bv. in fabrieken)." },
  { v: "Wat is kettingpapier?", a: "Een lange strook papier met gaatjes aan de zijkant die door de printer getrokken wordt.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Kettingpapier: een lange strook papier aan elkaar met gaatjes aan de zijkanten, die door de printer getrokken wordt. Zo kan hij zonder onderbreking veel na elkaar printen." },
  { v: "Wat betekent doordrukken en waarom kan enkel een matrixprinter dat?", a: "Meerdere lagen (doorslagpapier) in één keer bedrukken; omdat de pennetjes echt op het papier slaan.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Doordrukken: omdat de pennetjes echt op het papier slaan, kan hij doorslagpapier (meerdere lagen) bedrukken. Zo heb je in één keer een origineel én een kopie, bv. voor een leveringsbon. Dat kan geen andere printer." },
  { v: "Wat heeft een thermische printer nodig?", a: "Speciaal (thermisch) papier dat zwart wordt waar het verwarmd wordt.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Een thermische printer werkt met warmte en heeft speciaal papier nodig: thermisch papier dat zwart wordt waar het verwarmd wordt. Er is dus geen inkt nodig. Je vindt ze vooral voor kastickets in winkels. Nadeel: de print vervaagt na een tijd en in de zon." },
  { v: "Wat is het nadeel van thermische prints?", a: "Ze vervagen na een tijd en in de zon.", o: "Printer: matrix, thermisch en inkjet", extra: true,
    uitleg: "Een thermische printer werkt met warmte en heeft speciaal papier nodig: thermisch papier dat zwart wordt waar het verwarmd wordt. Er is dus geen inkt nodig. Je vindt ze vooral voor kastickets in winkels. Nadeel: de print vervaagt na een tijd en in de zon." },
  { v: "Hoe werkt een inkjetprinter?", a: "Kleine spuitmondjes spuiten druppeltjes vloeibare inkt op het papier.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Een inkjetprinter spuit met kleine spuitmondjes (nozzles) heel kleine druppeltjes vloeibare inkt op het papier. De meest voorkomende printer voor thuis." },
  { v: "Wat kan er gebeuren als je een inkjet lang niet gebruikt?", a: "De inkt in de spuitmondjes droogt in.", o: "Printer: matrix, thermisch en inkjet",
    uitleg: "Goed voor kleine hoeveelheden, bijvoorbeeld thuisgebruik. Ook goed voor kleurenfoto's. Gebruik je hem lang niet, dan kan de inkt in de spuitmondjes indrogen." },

  // ===== Printer: laserprinter in 7 stappen (slide 22) =====
  { v: "Geef de 7 stappen van een laserprinter in volgorde, met de Engelse naam.", a: "1. Kuisen van de rol (cleaning)\n2. Drum elektrisch neutraal maken (erasing)\n3. Negatief laden (conditioning)\n4. Laser laten schrijven → positieve ladingen (writing)\n5. Drum neemt op positieve ladingen inkt op (developing)\n6. Papier rollen (transferring)\n7. Papier verwarmen om te fixeren (fusing)", o: "Printer: laserprinter in 7 stappen",
    uitleg: "De drum (rol) is een cilinder die elektrisch geladen kan worden.\n\nHet idee: eerst maak je de drum proper en neutraal (1-2), dan geef je hem overal een negatieve lading (3). De laser 'tekent' de tekst op de drum: waar hij komt, wordt de lading positief (4). De inkt (een fijn poeder, toner) blijft alleen hangen op die positieve plekken (5). Het papier rolt langs de drum en neemt het poeder over (6). Tot slot smelt warmte het poeder vast op het papier (7). Daarom is papier uit een laserprinter warm." },
  { v: "Wat gebeurt er bij cleaning?", a: "De rol wordt gekuist.", o: "Printer: laserprinter in 7 stappen",
    uitleg: "1. Kuisen van de rol (cleaning): eerst wordt de drum gereinigd: een mesje schraapt de overgebleven toner van de vorige pagina eraf." },
  { v: "Wat gebeurt er bij erasing?", a: "De drum wordt elektrisch neutraal gemaakt.", o: "Printer: laserprinter in 7 stappen",
    uitleg: "2. Drum elektrisch neutraal maken (erasing): de oude elektrische ladingen van de vorige pagina worden gewist, zodat de drum neutraal is (geen lading). Zo blijft er geen \"spookbeeld\" van de vorige pagina." },
  { v: "Wat gebeurt er bij conditioning?", a: "De drum wordt negatief geladen.", o: "Printer: laserprinter in 7 stappen",
    uitleg: "3. Negatief laden (conditioning): de hele drum krijgt een gelijkmatige negatieve lading." },
  { v: "Wat gebeurt er bij writing?", a: "De laser schrijft: er ontstaan positieve ladingen.", o: "Printer: laserprinter in 7 stappen",
    uitleg: "4. Laser laten schrijven → positieve ladingen (writing): de laser schijnt op de plaatsen waar er iets geprint moet worden (de letters en afbeeldingen). Waar de laser komt, verandert de lading naar positief. Zo staat het beeld als een onzichtbaar patroon van ladingen op de drum." },
  { v: "Wat gebeurt er bij developing?", a: "De drum neemt op de positieve ladingen inkt op.", o: "Printer: laserprinter in 7 stappen",
    uitleg: "5. Drum neemt op positieve ladingen inkt op (developing): de toner wordt negatief geladen. Omdat tegengestelde ladingen elkaar aantrekken, blijft het negatieve tonerpoeder enkel kleven op de positieve plaatsen (waar de laser schreef). Nu is het beeld zichtbaar op de drum, in poeder." },
  { v: "Wat gebeurt er bij transferring?", a: "Het papier rolt; waar positieve ladingen zaten, komt nu poeder op het papier.", o: "Printer: laserprinter in 7 stappen",
    uitleg: "6. Papier rollen (transferring): het papier rolt langs de drum en krijgt zelf een lading, zodat het de toner van de drum naar zich toe trekt. Waar positieve ladingen zaten, komt nu poeder op het papier." },
  { v: "Wat gebeurt er bij fusing?", a: "Het papier wordt verwarmd om te fixeren.", o: "Printer: laserprinter in 7 stappen",
    uitleg: "7. Papier verwarmen om te fixeren (fusing): het poeder ligt nog los op het papier; je zou het zo kunnen wegvegen. Daarom gaat het papier door de fuser: twee hete rollen die de toner smelten en in het papier drukken. Daarom is een blad dat net uit een laserprinter komt warm." },
  { v: "Welke stap van de laserprinter is stap 4, en welke stap 6?", a: "4. Writing (laser laten schrijven)\n6. Transferring (papier rollen)", o: "Printer: laserprinter in 7 stappen",
    uitleg: "4. Laser laten schrijven → positieve ladingen (writing): de laser schijnt op de plaatsen waar er iets geprint moet worden (de letters en afbeeldingen). Waar de laser komt, verandert de lading naar positief. Zo staat het beeld als een onzichtbaar patroon van ladingen op de drum." },
  { v: "Welke stap komt na conditioning?", a: "Writing (laser laten schrijven).", o: "Printer: laserprinter in 7 stappen",
    uitleg: "4. Laser laten schrijven → positieve ladingen (writing): de laser schijnt op de plaatsen waar er iets geprint moet worden (de letters en afbeeldingen). Waar de laser komt, verandert de lading naar positief. Zo staat het beeld als een onzichtbaar patroon van ladingen op de drum." },
  { v: "Op welke ladingen neemt de drum inkt op: positieve of negatieve?", a: "Op de positieve ladingen.", o: "Printer: laserprinter in 7 stappen",
    uitleg: "5. Drum neemt op positieve ladingen inkt op (developing): de toner wordt negatief geladen. Omdat tegengestelde ladingen elkaar aantrekken, blijft het negatieve tonerpoeder enkel kleven op de positieve plaatsen (waar de laser schreef). Nu is het beeld zichtbaar op de drum, in poeder." },
  { v: "Toner", a: "De 'inkt' van een laserprinter heet toner: een heel fijn poeder. Bij fusing smelt de warmte de toner vast in het papier.", o: "Printer: laserprinter in 7 stappen", extra: true,
    uitleg: "Een laserprinter werkt niet met vloeibare inkt maar met toner: een heel fijn poeder. Het hart van de printer is de drum (de trommel of rol): een cilinder met een speciale laag die elektrische lading kan vasthouden. Het principe: tegengestelde ladingen trekken elkaar aan, gelijke ladingen stoten elkaar af. De laser \"tekent\" met elektrische lading een onzichtbaar beeld op de drum, en het tonerpoeder blijft enkel daar plakken. Een laserprinter is snel en goedkoop per pagina, ideaal voor kantoren en grote hoeveelheden." },
  { v: "Wat doet de laser bij de stap writing, en hoe heet de 'inkt' van een laserprinter?", a: "Writing: de laser schrijft het beeld op de drum; daar ontstaan positieve ladingen.\nDe 'inkt' heet toner: een fijn poeder.", o: "Printer: laserprinter in 7 stappen",
    uitleg: "Het toner wordt aangetrokken door de plekken die de laser beschreven heeft, en daarna op het papier overgebracht.\n\nEen laserprinter werkt niet met vloeibare inkt maar met toner: een heel fijn poeder. Het hart van de printer is de drum (de trommel of rol): een cilinder met een speciale laag die elektrische lading kan vasthouden. Het principe: tegengestelde ladingen trekken elkaar aan, gelijke ladingen stoten elkaar af. De laser \"tekent\" met elektrische lading een onzichtbaar beeld op de drum, en het tonerpoeder blijft enkel daar plakken. Een laserprinter is snel en goedkoop per pagina, ideaal voor kantoren en grote hoeveelheden." },
  { v: "Waarom is papier warm als het uit een laserprinter komt?", a: "Door de laatste stap: fusing. Het papier wordt verwarmd om het tonerpoeder te fixeren.", o: "Printer: laserprinter in 7 stappen",
    uitleg: "Fusing = smelten: twee warme rollen drukken het tonerpoeder in het papier, zodat het niet meer afveegt. Daarom is een afdruk van een laserprinter warm.\n\n7. Papier verwarmen om te fixeren (fusing): het poeder ligt nog los op het papier; je zou het zo kunnen wegvegen. Daarom gaat het papier door de fuser: twee hete rollen die de toner smelten en in het papier drukken. Daarom is een blad dat net uit een laserprinter komt warm." },
  { v: "Waarmee print een laserprinter?", a: "Met toner: een fijn poeder.", o: "Printer: laserprinter in 7 stappen",
    uitleg: "Een laserprinter werkt niet met vloeibare inkt maar met toner: een heel fijn poeder. Het hart van de printer is de drum (de trommel of rol): een cilinder met een speciale laag die elektrische lading kan vasthouden. Het principe: tegengestelde ladingen trekken elkaar aan, gelijke ladingen stoten elkaar af. De laser \"tekent\" met elektrische lading een onzichtbaar beeld op de drum, en het tonerpoeder blijft enkel daar plakken. Een laserprinter is snel en goedkoop per pagina, ideaal voor kantoren en grote hoeveelheden." },
  { v: "Wat is de drum?", a: "De rol (trommel) die elektrische lading kan vasthouden.", o: "Printer: laserprinter in 7 stappen",
    uitleg: "Een laserprinter werkt niet met vloeibare inkt maar met toner: een heel fijn poeder. Het hart van de printer is de drum (de trommel of rol): een cilinder met een speciale laag die elektrische lading kan vasthouden. Het principe: tegengestelde ladingen trekken elkaar aan, gelijke ladingen stoten elkaar af. De laser \"tekent\" met elektrische lading een onzichtbaar beeld op de drum, en het tonerpoeder blijft enkel daar plakken. Een laserprinter is snel en goedkoop per pagina, ideaal voor kantoren en grote hoeveelheden." },
  { v: "Op welk principe werkt een laserprinter?", a: "Tegengestelde ladingen trekken elkaar aan.", o: "Printer: laserprinter in 7 stappen", extra: true,
    uitleg: "Een laserprinter werkt niet met vloeibare inkt maar met toner: een heel fijn poeder. Het hart van de printer is de drum (de trommel of rol): een cilinder met een speciale laag die elektrische lading kan vasthouden. Het principe: tegengestelde ladingen trekken elkaar aan, gelijke ladingen stoten elkaar af. De laser \"tekent\" met elektrische lading een onzichtbaar beeld op de drum, en het tonerpoeder blijft enkel daar plakken. Een laserprinter is snel en goedkoop per pagina, ideaal voor kantoren en grote hoeveelheden." },
  { v: "Waarvoor is een laserprinter ideaal?", a: "Kantoren en grote hoeveelheden (snel en goedkoop per pagina).", o: "Printer: laserprinter in 7 stappen", extra: true,
    uitleg: "Een laserprinter werkt niet met vloeibare inkt maar met toner: een heel fijn poeder. Het hart van de printer is de drum (de trommel of rol): een cilinder met een speciale laag die elektrische lading kan vasthouden. Het principe: tegengestelde ladingen trekken elkaar aan, gelijke ladingen stoten elkaar af. De laser \"tekent\" met elektrische lading een onzichtbaar beeld op de drum, en het tonerpoeder blijft enkel daar plakken. Een laserprinter is snel en goedkoop per pagina, ideaal voor kantoren en grote hoeveelheden." },
  { v: "Noem de 7 stappen in volgorde (Engels).", a: "Cleaning, erasing, conditioning, writing, developing, transferring, fusing.", o: "Printer: laserprinter in 7 stappen",
    uitleg: "Goed om te weten: Ezelsbrug voor de volgorde: Cleaning – Erasing – Conditioning – Writing – Developing – Transferring – Fusing. Daarna begint de cyclus voor de volgende pagina weer bij stap 1." },
  { v: "Laserprinter, stap 1: wat gebeurt er bij cleaning?", a: "De rol wordt gekuist: overgebleven toner wordt eraf geschraapt.", o: "Printer: laserprinter in 7 stappen",
    uitleg: "1. Kuisen van de rol (cleaning): eerst wordt de drum gereinigd: een mesje schraapt de overgebleven toner van de vorige pagina eraf." },
  { v: "Laserprinter, stap 2: wat gebeurt er bij erasing?", a: "De drum wordt elektrisch neutraal gemaakt (oude ladingen gewist).", o: "Printer: laserprinter in 7 stappen",
    uitleg: "2. Drum elektrisch neutraal maken (erasing): de oude elektrische ladingen van de vorige pagina worden gewist, zodat de drum neutraal is (geen lading). Zo blijft er geen \"spookbeeld\" van de vorige pagina." },
  { v: "Laserprinter: waarom is erasing nodig?", a: "Zodat er geen spookbeeld van de vorige pagina overblijft.", o: "Printer: laserprinter in 7 stappen", extra: true,
    uitleg: "2. Drum elektrisch neutraal maken (erasing): de oude elektrische ladingen van de vorige pagina worden gewist, zodat de drum neutraal is (geen lading). Zo blijft er geen \"spookbeeld\" van de vorige pagina." },
  { v: "Laserprinter: waarom kleeft de toner enkel op de positieve plaatsen?", a: "De toner is negatief geladen en tegengestelde ladingen trekken elkaar aan.", o: "Printer: laserprinter in 7 stappen", extra: true,
    uitleg: "5. Drum neemt op positieve ladingen inkt op (developing): de toner wordt negatief geladen. Omdat tegengestelde ladingen elkaar aantrekken, blijft het negatieve tonerpoeder enkel kleven op de positieve plaatsen (waar de laser schreef). Nu is het beeld zichtbaar op de drum, in poeder." },
  { v: "Laserprinter, stap 7: wat gebeurt er bij fusing?", a: "Het papier wordt verwarmd om de toner te fixeren (smelten in het papier).", o: "Printer: laserprinter in 7 stappen",
    uitleg: "7. Papier verwarmen om te fixeren (fusing): het poeder ligt nog los op het papier; je zou het zo kunnen wegvegen. Daarom gaat het papier door de fuser: twee hete rollen die de toner smelten en in het papier drukken. Daarom is een blad dat net uit een laserprinter komt warm." },
  { v: "Waarom is een blad uit een laserprinter warm?", a: "Door de fuser (hete rollen) in stap 7.", o: "Printer: laserprinter in 7 stappen",
    uitleg: "7. Papier verwarmen om te fixeren (fusing): het poeder ligt nog los op het papier; je zou het zo kunnen wegvegen. Daarom gaat het papier door de fuser: twee hete rollen die de toner smelten en in het papier drukken. Daarom is een blad dat net uit een laserprinter komt warm." },

  // ===== Stroomvoorziening (slide 23) =====
  { v: "Wat gebeurt er met het RAM-geheugen als de stroom wegvalt?", a: "Het verliest zijn inhoud.", o: "Stroomvoorziening",
    uitleg: "Het RAM-geheugen verliest zijn inhoud: RAM is vluchtig (zie Basisbegrippen). Alles wat in het werkgeheugen stond, is weg." },
  { v: "Wat betekent het wegvallen van stroom meestal?", a: "Dataverlies (tenzij recovery).", o: "Stroomvoorziening", imgAntwoord: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s23_ups.jpg",
    uitleg: "Dat betekent meestal dataverlies: werk dat je nog niet had opgeslagen, ben je kwijt. Een bestand dat net weggeschreven werd, kan zelfs beschadigd raken." },
  { v: "Wat moet de stroomvoorziening opvangen bij het reguleren van de stroominput?", a: "Spikes.", o: "Stroomvoorziening" },
  { v: "Waarvoor staat UPS?", a: "Uninterruptable Power Supply.", o: "Stroomvoorziening",
    uitleg: "Bij servers (en soms ook bij thuiscomputers) gebruikt men een UPS: Uninterruptible Power Supply, een ononderbreekbare stroomvoorziening. Dat is een toestel met een grote batterij tussen het stopcontact en de computer." },
  { v: "Hoe en hoe lang levert een UPS stroom?", a: "Met een batterij, voor ongeveer 1 uur.", o: "Stroomvoorziening",
    uitleg: "De batterij levert stroom voor ongeveer 1 uur. Genoeg om de stroompanne te overbruggen, of om alles netjes op te slaan en de computer veilig af te sluiten." },
  { v: "Waar wordt een UPS gebruikt?", a: "Bij servers (of soms ook bij thuiscomputers).", o: "Stroomvoorziening",
    uitleg: "Bij servers (en soms ook bij thuiscomputers) gebruikt men een UPS: Uninterruptible Power Supply, een ononderbreekbare stroomvoorziening. Dat is een toestel met een grote batterij tussen het stopcontact en de computer." },
  { v: "Wat gebruiken grote serverparken soms naast een UPS?", a: "Een dieselgenerator.", o: "Stroomvoorziening",
    uitleg: "In grote serverparken (datacenters) heeft men soms ook een dieselgenerator: de UPS overbrugt de eerste minuten, en daarna neemt de generator het over, zodat de servers uren of dagen kunnen blijven draaien." },
  { v: "Welk toestel zie je op deze foto, en waarvoor dient het?", a: "Een UPS (Uninterruptable Power Supply): die levert met een batterij ongeveer 1 uur stroom als de stroom wegvalt.", o: "Stroomvoorziening", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s23_ups.jpg",
    uitleg: "Op de foto zie je een UPS.\n\nBij servers (en soms ook bij thuiscomputers) gebruikt men een UPS: Uninterruptible Power Supply, een ononderbreekbare stroomvoorziening. Dat is een toestel met een grote batterij tussen het stopcontact en de computer." },
  { v: "Wat is een spike, en wat moet de stroomvoorziening opvangen bij het reguleren van de stroominput?", a: "Een spike is een korte, plotse piek in de spanning, bv. bij bliksem. De stroomvoorziening moet zulke spikes opvangen.", o: "Stroomvoorziening",
    uitleg: "Een te hoge spanning, ook al duurt ze maar heel kort, kan onderdelen van de computer beschadigen. Een goede voeding of een overspanningsbeveiliging vangt die pieken op.\n\nDe stroom uit het stopcontact is niet altijd perfect stabiel. Soms zijn er spikes (pieken): een plotse, korte overspanning, bv. door blikseminslag of het aan- en uitschakelen van zware toestellen. Zo'n piek kan de elektronica in je computer beschadigen. Een goede voeding of een overspanningsbeveiliging (een stekkerdoos met beveiliging) vangt die spikes op en regelt de stroom." },
  { v: "Waarom verliest RAM zijn inhoud bij een stroompanne, en waarvoor dient het uur dat een UPS geeft?", a: "RAM is volatile: het heeft stroom nodig om data te bewaren.\nHet uur van de UPS dient om alles netjes af te sluiten, of tot een generator start.", o: "Stroomvoorziening",
    uitleg: "UPS = Uninterruptible Power Supply: een toestel met een batterij dat stroom geeft als het net uitvalt, voor ongeveer 1 uur.\n\nZonder UPS ben je alles kwijt wat nog niet opgeslagen was, en kan een bestand of schijf beschadigd raken.\n\nRAM heeft stroom nodig om zijn inhoud te bewaren (zie hoofdstuk II.2, werkgeheugen). Valt de stroom weg, dan ben je alles kwijt wat nog niet opgeslagen was. Recovery = een manier om toch iets terug te halen, bv. een automatisch opgeslagen kopie.\n\nEen UPS is een kast met een batterij tussen het stopcontact en de computer. Valt de stroom weg, dan neemt de batterij het over. Uninterruptable = niet te onderbreken." },
  { v: "Wat betekent het wegvallen van de stroom meestal?", a: "Dataverlies.", o: "Stroomvoorziening",
    uitleg: "Dat betekent meestal dataverlies: werk dat je nog niet had opgeslagen, ben je kwijt. Een bestand dat net weggeschreven werd, kan zelfs beschadigd raken." },
  { v: "Wanneer kan je na het wegvallen van de stroom toch iets terugkrijgen?", a: "Bij recovery: een automatisch opgeslagen herstelkopie.", o: "Stroomvoorziening",
    uitleg: "Tenzij recovery: sommige programma's (zoals Word) slaan automatisch om de paar minuten een herstelkopie op. Na het herstarten kan je dan een deel van je werk herstellen (recovery)." },
  { v: "Wat zijn spikes?", a: "Plotse, korte stroompieken (overspanning).", o: "Stroomvoorziening",
    uitleg: "De stroom uit het stopcontact is niet altijd perfect stabiel. Soms zijn er spikes (pieken): een plotse, korte overspanning, bv. door blikseminslag of het aan- en uitschakelen van zware toestellen. Zo'n piek kan de elektronica in je computer beschadigen. Een goede voeding of een overspanningsbeveiliging (een stekkerdoos met beveiliging) vangt die spikes op en regelt de stroom." },
  { v: "Wat kan een spike veroorzaken?", a: "Blikseminslag of het schakelen van zware toestellen.", o: "Stroomvoorziening", extra: true,
    uitleg: "De stroom uit het stopcontact is niet altijd perfect stabiel. Soms zijn er spikes (pieken): een plotse, korte overspanning, bv. door blikseminslag of het aan- en uitschakelen van zware toestellen. Zo'n piek kan de elektronica in je computer beschadigen. Een goede voeding of een overspanningsbeveiliging (een stekkerdoos met beveiliging) vangt die spikes op en regelt de stroom." },
  { v: "Waarom moet je spikes opvangen?", a: "Ze kunnen de elektronica beschadigen.", o: "Stroomvoorziening", extra: true,
    uitleg: "De stroom uit het stopcontact is niet altijd perfect stabiel. Soms zijn er spikes (pieken): een plotse, korte overspanning, bv. door blikseminslag of het aan- en uitschakelen van zware toestellen. Zo'n piek kan de elektronica in je computer beschadigen. Een goede voeding of een overspanningsbeveiliging (een stekkerdoos met beveiliging) vangt die spikes op en regelt de stroom." },
  { v: "Waarmee vang je spikes op?", a: "Door de stroominput te reguleren, bv. met een overspanningsbeveiliging.", o: "Stroomvoorziening",
    uitleg: "De stroom uit het stopcontact is niet altijd perfect stabiel. Soms zijn er spikes (pieken): een plotse, korte overspanning, bv. door blikseminslag of het aan- en uitschakelen van zware toestellen. Zo'n piek kan de elektronica in je computer beschadigen. Een goede voeding of een overspanningsbeveiliging (een stekkerdoos met beveiliging) vangt die spikes op en regelt de stroom." },
  { v: "Wat is een UPS?", a: "Een toestel met een batterij dat meteen stroom levert als de stroom uitvalt.", o: "Stroomvoorziening",
    uitleg: "Bij servers (en soms ook bij thuiscomputers) gebruikt men een UPS: Uninterruptible Power Supply, een ononderbreekbare stroomvoorziening. Dat is een toestel met een grote batterij tussen het stopcontact en de computer.\n\nAls de stroom plots uitvalt (een stroompanne), valt de computer meteen uit.\n\nValt de stroom weg, dan neemt de batterij het meteen over, zonder onderbreking: de computer merkt niets." },
  { v: "Een UPS levert ongeveer 1 uur stroom. Waarvoor dient dat uur?", a: "De panne overbruggen of alles opslaan en veilig afsluiten.", o: "Stroomvoorziening", extra: true,
    uitleg: "De batterij levert stroom voor ongeveer 1 uur. Genoeg om de stroompanne te overbruggen, of om alles netjes op te slaan en de computer veilig af te sluiten." },
  { v: "Wat gebruikt men extra in grote serverparken?", a: "Een dieselgenerator.", o: "Stroomvoorziening",
    uitleg: "Bij servers (en soms ook bij thuiscomputers) gebruikt men een UPS: Uninterruptible Power Supply, een ononderbreekbare stroomvoorziening. Dat is een toestel met een grote batterij tussen het stopcontact en de computer." },
  { v: "Hoe werken UPS en dieselgenerator samen?", a: "De UPS overbrugt de eerste minuten, daarna neemt de generator over.", o: "Stroomvoorziening", extra: true,
    uitleg: "In grote serverparken (datacenters) heeft men soms ook een dieselgenerator: de UPS overbrugt de eerste minuten, en daarna neemt de generator het over, zodat de servers uren of dagen kunnen blijven draaien." },
  { v: "Wat toont de foto bij stroomvoorziening?", a: "Een donkergrijze UPS-kast met een schermpje en knoppen vooraan.", o: "Stroomvoorziening", img: "afbeeldingen/ITdeel2les8_randapparatuur/l8_s23_ups.jpg",
    uitleg: "Wat zie je op de afbeelding? Rechtsonder een foto van een UPS: een donkergrijze, rechthoekige kast die op de grond staat, met vooraan een klein schermpje en knoppen om de status (bv. batterijniveau) te zien." },
];

